window.LIVRO = {"meta":{"fonte":"Tratado de Fisiologia Médica, capítulo 35, páginas 469 a 474","credito":"Material organizado por Mateus Couto, acadêmico de medicina","hash":"c31a143c50be","total_blocos":30,"total_questoes":207,"por_tipo":{"DIRETA":48,"MULTIPLA":44,"VF":60,"DISSERTATIVA":55},"total_imagens":56},"blocos":[{"numero":1,"id":"bloco-01","titulo":"Exposição contínua a microrganismos e os dois modos de defesa","sensivel":false,"busca_imagens":"flora microbiana normal pele boca intestino","busca_videos":"defesa do organismo contra infecção fagocitose anticorpos","texto":[{"t":"h","texto":"Resistência do Corpo à Infecção: I. Leucócitos, Granulócitos, Sistema Monocítico-Macrofágico e Inflamação"},{"t":"p","texto":"Nossos corpos são expostos continuamente a bactérias, vírus, fungos e parasitas, todos encontrados, nas condições normais e em graus variáveis, na pele, na boca, nas vias respiratórias, no trato intestinal, nas membranas de revestimento dos olhos e mesmo no trato urinário. Muitos desses agentes infecciosos são capazes de produzir anormalidades graves nas funções fisiológicas ou até mesmo morte, se invadirem os tecidos profundos. Além disso, somos de forma intermitente expostos a outras bactérias e vírus extremamente infecciosos, além dos presentes nas condições normais, e esses microrganismos podem causar doenças agudas letais, como pneumonia, infecções estreptocócicas e febre tifoide."},{"t":"p","texto":"Nossos corpos têm sistema especial para combater as diferentes infecções e agentes tóxicos. Esse sistema é formado pelos leucócitos (glóbulos brancos) e células teciduais derivadas dos leucócitos. Essas células atuam em conjunto, por dois modos, para impedir a doença: (1) pela verdadeira destruição das bactérias ou dos vírus, porfagocitose e (2) pela formação de anticorpos e linfócitos sensibilizados, capazes de destruir ou inativar o invasor. Este capítulo trata do primeiro desses processos, e o Capítulo 34, do segundo."}],"imagens":[{"id":"bloco-01-a","arquivo":"bloco-01-a.jpg","largura":768,"altura":1376,"alt":"Bloco 1, imagem 1 de 2: CONTATO · BARREIRAS DO CORPO · IMPEDEM INVASÃO PROFUNDA"},{"id":"bloco-01-b","arquivo":"bloco-01-b.jpg","largura":768,"altura":1376,"alt":"Bloco 1, imagem 2 de 2: MICRÓBIO · LEUCÓCITOS · COMBATEM INVASORES"}],"questoes":[{"id":"Q01.01","tipo":"DIRETA","enunciado":"Qual célula sanguínea integra o sistema de defesa contra infecções?","alternativas":{},"resposta":"Leucócito.","justificativa":"Os leucócitos e as células teciduais deles derivadas compõem esse sistema protetor.","dica":"Pense nos glóbulos brancos."},{"id":"Q01.02","tipo":"DIRETA","enunciado":"Qual processo destrói invasores por ingestão celular?","alternativas":{},"resposta":"Fagocitose.","justificativa":"A fagocitose constitui o modo de defesa que destrói bactérias ou vírus por ingestão celular.","dica":"O nome remete a engolir."},{"id":"Q01.03","tipo":"MULTIPLA","enunciado":"Em condições normais, qual local pode abrigar microrganismos aos quais o corpo fica continuamente exposto?","alternativas":{"A":"Membranas oculares.","B":"Cavidade peritoneal.","C":"Líquido cefalorraquidiano.","D":"Espaço pleural."},"resposta":"A","justificativa":"As membranas de revestimento dos olhos são locais de exposição habitual. A cavidade peritoneal não integra as superfícies corporais enumeradas.","dica":"Considere superfícies de contato com o meio."},{"id":"Q01.04","tipo":"VF","enunciado":"A invasão dos tecidos profundos por agentes presentes em superfícies corporais pode causar disfunção fisiológica grave ou morte.","alternativas":{},"resposta":"Verdadeiro","justificativa":"O risco grave surge quando esses agentes invadem tecidos profundos.","dica":"Diferencie exposição superficial de invasão."},{"id":"Q01.05","tipo":"DISSERTATIVA","enunciado":"Quais são os dois modos de ação do sistema de defesa formado por leucócitos e células deles derivadas?","alternativas":{},"resposta":"Fagocitose e formação de anticorpos e linfócitos sensibilizados.","justificativa":"A defesa ocorre pela destruição fagocítica ou pela produção de componentes capazes de destruir ou inativar o invasor.","dica":"Uma via engloba; a outra reconhece."},{"id":"Q01.06","tipo":"MULTIPLA","enunciado":"Assinale a exceção entre os locais de exposição habitual do corpo a microrganismos.","alternativas":{"A":"Pele.","B":"Trato urinário.","C":"Tecidos profundos.","D":"Vias respiratórias."},"resposta":"C","justificativa":"Tecidos profundos aparecem como local de invasão capaz de causar doença grave, enquanto pele, trato urinário e vias respiratórias são locais de exposição habitual. O trato urinário pode surpreender, mas integra essa relação.","dica":"Distinga superfícies expostas de tecidos invadidos."},{"id":"Q01.07","tipo":"VF","enunciado":"Pneumonia, infecções estreptocócicas e febre tifoide são doenças crônicas da exposição contínua habitual.","alternativas":{},"resposta":"Falso","justificativa":"Essas três doenças exemplificam infecções agudas potencialmente letais associadas a exposições intermitentes.","dica":"Pense nos exemplos de infecção aguda."},{"id":"Q01.08","tipo":"DISSERTATIVA","enunciado":"Além de bactérias, vírus e fungos, qual outro grupo de agentes participa da exposição contínua do corpo?","alternativas":{},"resposta":"Parasitas.","justificativa":"Parasitas integram a exposição contínua ao lado de bactérias, vírus e fungos.","dica":"Falta o grupo de organismos parasitários."},{"id":"Q01.09","tipo":"DISSERTATIVA","enunciado":"Cite as seis superfícies corporais de exposição habitual a microrganismos.","alternativas":{},"resposta":"Pele, boca, vias respiratórias, trato intestinal, membranas de revestimento dos olhos e trato urinário.","justificativa":"Essas superfícies entram em contato contínuo com bactérias, vírus, fungos ou parasitas em graus variáveis.","dica":"Percorra pele, mucosas e vias de eliminação."}]},{"numero":2,"id":"bloco-02","titulo":"Leucócitos: unidades móveis de defesa, origem e destino","sensivel":false,"busca_imagens":"leucócitos esfregaço de sangue periférico","busca_videos":"leucócitos origem e função fisiologia","texto":[{"t":"h","texto":"Leucócitos (Glóbulos Brancos)"},{"t":"p","texto":"Os leucócitos, também chamados glóbulos brancos, são as unidades móveis do sistema protetor do corpo. Eles são formados em parte na medula óssea {granulócitos, monócitos e alguns linfócitos) e, em outra, no tecido Enfático {linfócitos e plasmócitos). Após sua formação, eles são transportados pelo sangue para diversas partes do corpo, onde forem necessários."},{"t":"p","texto":"O valor real dos glóbulos brancos é que, em sua maioria, eles são especificamente transportados para áreas de infecção e inflamação graves, promovendo a rápida e potente defesa contra agentes infecciosos. Como veremos mais adiante, os granulócitos e os monócitos têm capacidade especial para “detectar e destruir” um invasor estranho."}],"imagens":[{"id":"bloco-02-a","arquivo":"bloco-02-a.jpg","largura":768,"altura":1376,"alt":"Bloco 2, imagem 1 de 1: INFECÇÃO · LEUCÓCITOS · VIAJAM PELO SANGUE"}],"questoes":[{"id":"Q02.01","tipo":"DIRETA","enunciado":"Qual é a denominação alternativa dos leucócitos?","alternativas":{},"resposta":"Glóbulos brancos.","justificativa":"Leucócitos e glóbulos brancos são denominações da mesma população celular.","dica":"É a denominação usada no hemograma."},{"id":"Q02.02","tipo":"MULTIPLA","enunciado":"Qual associação entre célula e principal local de formação está correta?","alternativas":{"A":"Granulócito — tecido linfoide.","B":"Monócito — medula óssea.","C":"Plasmócito — sangue.","D":"Linfócito — capilar sanguíneo."},"resposta":"B","justificativa":"A medula óssea forma monócitos. Granulócitos se originam na medula, e não no tecido linfático.","dica":"Separe a origem medular da linfoide."},{"id":"Q02.03","tipo":"VF","enunciado":"Após sua formação, os leucócitos são transportados pelo sangue até regiões onde são necessários.","alternativas":{},"resposta":"Verdadeiro","justificativa":"O sangue funciona como via de transporte dessas unidades móveis de defesa.","dica":"Pense no trajeto entre origem e destino."},{"id":"Q02.04","tipo":"DISSERTATIVA","enunciado":"Quais duas populações leucocitárias são destacadas por detectar e destruir invasores estranhos?","alternativas":{},"resposta":"Granulócitos e monócitos.","justificativa":"Essas populações têm capacidade especial de detectar e destruir agentes invasores.","dica":"Uma é granular; a outra origina macrófagos."},{"id":"Q02.05","tipo":"VF","enunciado":"A maioria dos leucócitos é direcionada a áreas de infecção e inflamação graves, onde promove defesa rápida.","alternativas":{},"resposta":"Verdadeiro","justificativa":"O transporte direcionado para essas áreas explica o valor defensivo dessas células.","dica":"Considere o local de recrutamento."},{"id":"Q02.06","tipo":"DIRETA","enunciado":"Qual tecido, além da medula óssea, participa da formação de leucócitos?","alternativas":{},"resposta":"Tecido linfático.","justificativa":"Linfócitos e plasmócitos são formados no tecido linfático, enquanto outras populações se formam na medula.","dica":"Relacione-o aos linfócitos."}]},{"numero":3,"id":"bloco-03","titulo":"Seis tipos de leucócitos, granulócitos e funções gerais","sensivel":false,"busca_imagens":"tipos de leucócitos neutrófilo eosinófilo basófilo monócito linfócito","busca_videos":"tipos de leucócitos e suas funções","texto":[{"t":"h","texto":"Características Gerais dos Leucócitos"},{"t":"p","texto":"Tipos de Glóbulos Brancos. Seis tipos de glóbulos brancos estão presentes no sangue. Eles são os neutrófilos polimorfonucleares, eosinófilos polimorfonucleares, basófdos polimorfonucleares, monócitos, linfócitos e, ocasionalmente, plasmócitos. Além desses, é encontrado grande número de plaquetas, que são fragmentos de outro tipo de célula semelhante aos leucócitos encontrados na medula óssea, o megacariócito. Os três primeiros tipos de células, as células polimorfonucleares, têm aparência granular, como mostrado pelas células de números 7 , 10 e 12 na Figura 33-1, e por esse motivo são chamados granulócitos ou, na terminologia clínica, “polis” devido a seus múltiplos núcleos."},{"t":"p","texto":"Os granulócitos e os monócitos protegem o corpo contra microrganismos invasores, principalmente por meio de sua ingestão {i. e., pela fagocitose). Os linfócitos e os plasmócitos atuam principalmente em conexão com o sistema imune; isso é discutido no Capítulo 34. Por fim, a função das plaquetas é, especificamente, a de ativar o mecanismo da coagulação sanguínea, discutido no Capítulo 36."}],"imagens":[{"id":"bloco-03-a","arquivo":"bloco-03-a.jpg","largura":768,"altura":1376,"alt":"Bloco 3, imagem 1 de 3: HEMOGRAMA · TIPOS DE LEUCÓCITOS · DEFESA DO CORPO"},{"id":"bloco-03-b","arquivo":"bloco-03-b.jpg","largura":768,"altura":1376,"alt":"Bloco 3, imagem 2 de 3: HEMOGRAMA · GRANULÓCITOS · PARTICIPAM DA DEFESA"},{"id":"bloco-03-c","arquivo":"bloco-03-c.jpg","largura":768,"altura":1376,"alt":"Bloco 3, imagem 3 de 3: CORTE · LEUCÓCITOS E PLAQUETAS · DEFESA E COAGULAÇÃO"}],"questoes":[{"id":"Q03.01","tipo":"DIRETA","enunciado":"Como são chamados, em conjunto, neutrófilos, eosinófilos e basófilos polimorfonucleares?","alternativas":{},"resposta":"Granulócitos.","justificativa":"Essas três populações apresentam aparência granular e constituem os granulócitos.","dica":"O nome descreve o citoplasma."},{"id":"Q03.02","tipo":"DIRETA","enunciado":"De qual célula medular derivam as plaquetas?","alternativas":{},"resposta":"Megacariócito.","justificativa":"As plaquetas são fragmentos do megacariócito encontrado na medula óssea.","dica":"Procure a grande célula precursora."},{"id":"Q03.03","tipo":"MULTIPLA","enunciado":"Qual população é encontrada apenas ocasionalmente entre os seis tipos de glóbulos brancos presentes no sangue?","alternativas":{"A":"Basófilos maduros.","B":"Monócitos.","C":"Plasmócitos.","D":"Linfócitos."},"resposta":"C","justificativa":"Plasmócitos aparecem ocasionalmente no sangue. Basófilos integram o trio de granulócitos, sem a ressalva de presença ocasional.","dica":"É uma célula ligada ao sistema imune."},{"id":"Q03.04","tipo":"VF","enunciado":"Granulócitos e monócitos combatem microrganismos invasores principalmente por fagocitose.","alternativas":{},"resposta":"Verdadeiro","justificativa":"A ingestão dos invasores é a principal função protetora atribuída a esses grupos.","dica":"Lembre-se de qual grupo engole."},{"id":"Q03.05","tipo":"DISSERTATIVA","enunciado":"Qual é a função predominante das plaquetas?","alternativas":{},"resposta":"Ativar a coagulação sanguínea.","justificativa":"As plaquetas ativam o mecanismo da coagulação sanguínea.","dica":"Relacione-as à hemostasia."},{"id":"Q03.06","tipo":"MULTIPLA","enunciado":"Assinale a exceção entre os leucócitos polimorfonucleares de aparência granular.","alternativas":{"A":"Neutrófilo polimorfonuclear.","B":"Eosinófilo.","C":"Basófilo.","D":"Monócito circulante."},"resposta":"D","justificativa":"Monócitos não pertencem ao trio de polimorfonucleares granulares. Basófilos podem confundir por sua baixa frequência, mas são granulócitos.","dica":"Identifique o integrante da linhagem mononuclear."},{"id":"Q03.07","tipo":"VF","enunciado":"Linfócitos e plasmócitos protegem o corpo principalmente pela ingestão direta de microrganismos.","alternativas":{},"resposta":"Falso","justificativa":"Essas células atuam predominantemente em conexão com o sistema imune; a fagocitose predomina em granulócitos e monócitos.","dica":"Pense na defesa específica."},{"id":"Q03.08","tipo":"DISSERTATIVA","enunciado":"Qual característica morfológica fundamenta a designação clínica “polis” para os granulócitos?","alternativas":{},"resposta":"Múltiplos lobos nucleares.","justificativa":"A denominação clínica se relaciona à aparência polimorfonuclear dos três granulócitos.","dica":"Examine o núcleo."},{"id":"Q03.09","tipo":"MULTIPLA","enunciado":"Assinale as duas afirmações corretas. I. Granulócitos e monócitos agem principalmente por fagocitose. II. Linfócitos e plasmócitos ativam a coagulação. III. Plaquetas participam da ativação da coagulação. IV. Monócitos integram o trio polimorfonuclear.","alternativas":{"A":"I e II.","B":"I e III.","C":"II e IV.","D":"III e IV."},"resposta":"B","justificativa":"I e III estão corretas: granulócitos e monócitos fagocitam, e plaquetas ativam a coagulação. II confunde a função imune de linfócitos e plasmócitos com a função plaquetária; IV também é falsa.","dica":"Separe os grupos por função e morfologia."}]},{"numero":4,"id":"bloco-04","titulo":"Concentrações dos leucócitos e das plaquetas no sangue","sensivel":false,"busca_imagens":"leucograma valores de referência diferencial","busca_videos":"leucograma interpretação contagem diferencial","texto":[{"t":"p","subtitulo":"Concentrações dos Diferentes Glóbulos Brancos no","texto":"Sangue. O ser humano adulto tem cerca de 7.000 leucócitos por microlitro de sangue (em comparação com 5 milhões de hemácias). Do total de leucócitos, as porcentagens normais dos diferentes tipos de células são as seguintes:"},{"t":"tabela","linhas":[["Neutrófilos polimorfonucleares","62,0%"],["Eosinófilos polimorfonucleares","2,3%"],["Basófilos polimorfonucleares","0,4%"],["Monócitos","5,3%"],["Linfócitos","30,0%"]]},{"t":"p","texto":"O número de plaquetas que são somente fragmentos de células em cada microlitro de sangue é normalmente de cerca de 300.000."}],"imagens":[{"id":"bloco-04-a","arquivo":"bloco-04-a.jpg","largura":768,"altura":1376,"alt":"Bloco 4, imagem 1 de 2: HEMOGRAMA · LEUCÓCITOS · DEFENDEM O CORPO"},{"id":"bloco-04-b","arquivo":"bloco-04-b.jpg","largura":768,"altura":1376,"alt":"Bloco 4, imagem 2 de 2: HEMOGRAMA · NEUTRÓFILOS · FAGOCITAM MICRÓBIOS"}],"questoes":[{"id":"Q04.01","tipo":"DIRETA","enunciado":"Qual é a contagem aproximada de leucócitos por microlitro de sangue no adulto?","alternativas":{},"resposta":"7.000/µL.","justificativa":"A concentração média é de cerca de 7.000 leucócitos por microlitro.","dica":"Compare com os milhões de hemácias."},{"id":"Q04.02","tipo":"DIRETA","enunciado":"Qual leucócito apresenta a maior proporção no diferencial leucocitário normal?","alternativas":{},"resposta":"Neutrófilo.","justificativa":"Neutrófilos representam 62,0% dos leucócitos, a maior fração da tabela.","dica":"É a parcela superior à metade."},{"id":"Q04.03","tipo":"MULTIPLA","enunciado":"Qual porcentagem corresponde aos linfócitos no diferencial leucocitário normal?","alternativas":{"A":"5,30%.","B":"30,0%.","C":"62,00%.","D":"2,3%."},"resposta":"B","justificativa":"Os linfócitos representam 30,0%. O valor de 5,3% corresponde aos monócitos, distração possível entre células mononucleares.","dica":"É a segunda maior fração."},{"id":"Q04.04","tipo":"VF","enunciado":"Os eosinófilos correspondem a 2,3% dos leucócitos no diferencial leucocitário normal.","alternativas":{},"resposta":"Verdadeiro","justificativa":"Essa é a proporção atribuída aos eosinófilos polimorfonucleares.","dica":"Situa-se entre monócitos e basófilos."},{"id":"Q04.05","tipo":"DISSERTATIVA","enunciado":"Ordene neutrófilos, linfócitos, monócitos, eosinófilos e basófilos por frequência decrescente.","alternativas":{},"resposta":"Neutrófilos, linfócitos, monócitos, eosinófilos e basófilos.","justificativa":"As proporções são, respectivamente, 62,0%, 30,0%, 5,3%, 2,3% e 0,4%.","dica":"Comece com as duas populações predominantes."},{"id":"Q04.06","tipo":"MULTIPLA","enunciado":"Qual par de concentrações por microlitro de sangue corresponde às contagens normais?","alternativas":{"A":"Hemácias 5 milhões; plaquetas 300 mil.","B":"Hemácias 300 mil; plaquetas 5 milhões.","C":"Hemácias 7 mil; plaquetas 300 mil por µL.","D":"Hemácias 5 milhões; plaquetas 7 mil."},"resposta":"A","justificativa":"Há cerca de 5 milhões de hemácias e 300.000 plaquetas por microlitro. A alternativa D troca a contagem de plaquetas pela de leucócitos.","dica":"Distinga células vermelhas, fragmentos e células brancas."},{"id":"Q04.07","tipo":"VF","enunciado":"Basófilos correspondem a 5,3% dos leucócitos no diferencial normal.","alternativas":{},"resposta":"Falso","justificativa":"Basófilos representam 0,4%; 5,3% corresponde aos monócitos.","dica":"Procure o menor valor da tabela."},{"id":"Q04.08","tipo":"DIRETA","enunciado":"Qual é a proporção de monócitos no diferencial leucocitário normal?","alternativas":{},"resposta":"5,3%.","justificativa":"Monócitos correspondem a 5,3% do total de leucócitos.","dica":"Fica abaixo dos linfócitos e acima dos eosinófilos."},{"id":"Q04.09","tipo":"DISSERTATIVA","enunciado":"Qual a contagem aproximada de plaquetas por microlitro de sangue?","alternativas":{},"resposta":"300.000/µL.","justificativa":"O valor normal aproximado é de 300 mil fragmentos plaquetários por microlitro.","dica":"São mais numerosas que os leucócitos."}]},{"numero":5,"id":"bloco-05","titulo":"Gênese dos leucócitos: linhagens mielocítica e linfocítica","sensivel":false,"busca_imagens":"hematopoese esquema linhagem mieloide linfoide","busca_videos":"hematopoese linhagem mieloide e linfoide","texto":[{"t":"h","texto":"Gênese dos Mielócitos"},{"t":"h","texto":"Gênese dos Linfócitos"},{"t":"leg","texto":"Figura 33-1 Gênese dos leucócitos. As diferentes células da série dos mielócitos são 7, mieloblasto; 2, promielócito; 3, megacariócito; 4, mielócito neutrófilo; 5, metamielócito neutrófilo jovem; 6, metamielócito neutrófilo \"em bastão\"; 7, neutrófilo polimorfonuclear; 8, mielócito eosinófilo; 9, metamielócito eosinófilo; 10, eosinófilo polimorfonuclear; 7 7, mielócito basófilo; 72, basófilo polimorfonuclear; 73-76, estágios da formação do monócito."},{"t":"h","texto":"Gênese dos Leucócitos"},{"t":"p","texto":"A diferenciação inicial das células-tronco hematopoéticas pluripotenciais nos quatro tipos de células-tronco comprometidas é mostrada na Figura 32-2 do capítulo anterior. Além das células comprometidas para formar as hemácias, são formadas duas grandes linhagens de leucócitos, as linhagens mielocítica e linfocítica. O lado esquerdo da Figura 33-1 mostra a linhagem mielocítica, começando com o mieloblasto-, o lado direito mostra a linhagem linfocítica, começando com o linfoblasto."}],"imagens":[{"id":"bloco-05-a","arquivo":"bloco-05-a.jpg","largura":768,"altura":1376,"alt":"Bloco 5, imagem 1 de 2: MEDULA ÓSSEA · CÉLULA-TRONCO · ORIGINA LINHAGENS"},{"id":"bloco-05-b","arquivo":"bloco-05-b.jpg","largura":768,"altura":1376,"alt":"Bloco 5, imagem 2 de 2: MEDULA ÓSSEA · LINHAGEM MIELOIDE · FORMA GRANULÓCITOS E MONÓCITOS"}],"questoes":[{"id":"Q05.01","tipo":"DIRETA","enunciado":"Qual célula inicia a linhagem mielocítica representada no esquema?","alternativas":{},"resposta":"Mieloblasto.","justificativa":"A linhagem mielocítica começa com o mieloblasto.","dica":"O prefixo indica a família medular."},{"id":"Q05.02","tipo":"DIRETA","enunciado":"Qual célula inicia a linhagem linfocítica representada no esquema?","alternativas":{},"resposta":"Linfoblasto.","justificativa":"A linhagem linfocítica começa com o linfoblasto.","dica":"É o blasto correspondente aos linfócitos."},{"id":"Q05.03","tipo":"MULTIPLA","enunciado":"Além da linhagem comprometida com hemácias, quais são as duas grandes linhagens de leucócitos?","alternativas":{"A":"Eritroide e plaquetária.","B":"Megacariocítica e monocítica.","C":"Neutrofílica e eosinofílica.","D":"Mielocítica e linfocítica."},"resposta":"D","justificativa":"O esquema separa os leucócitos em linhagens mielocítica e linfocítica. A dupla neutrofílica e eosinofílica descreve ramos celulares, não as duas grandes linhagens.","dica":"Pense nas duas famílias de origem."},{"id":"Q05.04","tipo":"VF","enunciado":"A diferenciação das células-tronco hematopoéticas pluripotenciais origina células-tronco comprometidas.","alternativas":{},"resposta":"Verdadeiro","justificativa":"A diferenciação inicial origina quatro tipos de células-tronco comprometidas.","dica":"A pluripotência precede o compromisso de linhagem."},{"id":"Q05.05","tipo":"DISSERTATIVA","enunciado":"Em quantos tipos de células-tronco comprometidas ocorre a diferenciação inicial?","alternativas":{},"resposta":"Quatro.","justificativa":"A diferenciação inicial indicada envolve quatro tipos de células-tronco comprometidas.","dica":"Conte os destinos iniciais citados."},{"id":"Q05.06","tipo":"VF","enunciado":"O metamielócito neutrófilo em bastão integra a sequência de formação do neutrófilo no esquema.","alternativas":{},"resposta":"Verdadeiro","justificativa":"A legenda inclui o metamielócito neutrófilo em bastão antes do neutrófilo polimorfonuclear.","dica":"Pense no estágio imediatamente anterior ao maduro."},{"id":"Q05.07","tipo":"DISSERTATIVA","enunciado":"Qual célula corresponde ao número 3 na série mielocítica da figura de gênese dos leucócitos?","alternativas":{},"resposta":"Megacariócito.","justificativa":"A legenda identifica o número 3 da série mielocítica como megacariócito.","dica":"É uma célula grande da medula."},{"id":"Q05.08","tipo":"DISSERTATIVA","enunciado":"Qual a sequência de maturação neutrofílica entre mieloblasto e neutrófilo polimorfonuclear?","alternativas":{},"resposta":"Mieloblasto, promielócito, mielócito neutrófilo, metamielócito jovem, metamielócito em bastão e neutrófilo polimorfonuclear.","justificativa":"A série do esquema passa por essas etapas antes de alcançar o neutrófilo maduro.","dica":"Localize o estágio em bastão perto do fim."},{"id":"Q05.09","tipo":"VF","enunciado":"A série mielocítica da figura contém precursores de neutrófilos, eosinófilos, basófilos e monócitos.","alternativas":{},"resposta":"Verdadeiro","justificativa":"A legenda identifica estágios de formação dessas quatro populações na série mielocítica.","dica":"Percorra os ramos identificados na figura."}]},{"numero":6,"id":"bloco-06","titulo":"Onde são formados e onde ficam armazenados","sensivel":false,"busca_imagens":"medula óssea e órgãos linfoides primários e secundários","busca_videos":"reserva medular de leucócitos liberação","texto":[{"t":"p","texto":"Os granulócitos e os monócitos só são formados na medula óssea. Os linfócitos e os plasmócitos são produzidos principalmente nos diversos tecidos linfogênicos — de modo especial, nos linfonodos, no baço, no timo, nas tonsilas e em vários bolsões de tecido linfoide em outras partes do corpo, como na medula óssea e nas chamadas placas de Peyer, por baixo do epitélio da parede do intestino."},{"t":"p","texto":"Os leucócitos formados na medula óssea ficam armazenados na medula até que sejam necessários no sistema circulatório. Quando surge essa necessidade, vários fatores provocam a liberação dos leucócitos (esses fatores são discutidos adiante). Normalmente, quantidade aproximada do triplo do número de leucócitos circulantes está armazenada na medula. Essa quantidade representa o suprimento para cerca de 6 dias dessas células."},{"t":"p","texto":"Os linfócitos são armazenados, em sua maioria, nos diversos tecidos linfoides, exceto por pequeno número que está sendo temporariamente transportado pelo sangue."}],"imagens":[{"id":"bloco-06-a","arquivo":"bloco-06-a.jpg","largura":768,"altura":1376,"alt":"Bloco 6, imagem 1 de 2: PRODUÇÃO · MEDULA ÓSSEA · PRODUZ GRANULÓCITOS"},{"id":"bloco-06-b","arquivo":"bloco-06-b.jpg","largura":768,"altura":1376,"alt":"Bloco 6, imagem 2 de 2: INFLAMAÇÃO · MEDULA ÓSSEA · GUARDA LEUCÓCITOS"}],"questoes":[{"id":"Q06.01","tipo":"DIRETA","enunciado":"Em que tecido são formados granulócitos e monócitos?","alternativas":{},"resposta":"Medula óssea.","justificativa":"A formação de ambos é atribuída à medula óssea.","dica":"É o principal sítio hematopoético."},{"id":"Q06.02","tipo":"MULTIPLA","enunciado":"Qual dos locais integra os tecidos linfogênicos produtores de linfócitos e plasmócitos?","alternativas":{"A":"Rim.","B":"Baço.","C":"Pele.","D":"Cérebro."},"resposta":"B","justificativa":"O baço integra os tecidos linfogênicos; o rim não exerce essa função no esquema de formação leucocitária.","dica":"Considere os órgãos linfoides."},{"id":"Q06.03","tipo":"VF","enunciado":"As placas de Peyer localizam-se sob o epitélio da parede intestinal e integram os tecidos linfogênicos.","alternativas":{},"resposta":"Verdadeiro","justificativa":"As placas de Peyer são bolsões de tecido linfoide sob o epitélio intestinal.","dica":"Lembre-se do tecido linfoide intestinal."},{"id":"Q06.04","tipo":"DISSERTATIVA","enunciado":"Cite quatro locais de produção de linfócitos e plasmócitos.","alternativas":{},"resposta":"Linfonodos, baço, timo e tonsilas.","justificativa":"Esses quatro locais constam da lista de tecidos linfogênicos, que inclui ainda outros bolsões linfoides.","dica":"Pense nos órgãos linfoides nomeados."},{"id":"Q06.05","tipo":"DIRETA","enunciado":"Onde ficam armazenados os leucócitos formados na medula antes de sua liberação?","alternativas":{},"resposta":"Medula óssea.","justificativa":"Eles permanecem armazenados na medula até serem necessários na circulação.","dica":"A reserva fica no local de formação."},{"id":"Q06.06","tipo":"MULTIPLA","enunciado":"A reserva medular normal de leucócitos equivale aproximadamente a qual relação com o número circulante?","alternativas":{"A":"Metade do contingente circulante.","B":"Igual ao contingente circulante.","C":"Triplo do contingente circulante.","D":"Décuplo do contingente circulante."},"resposta":"C","justificativa":"A medula armazena cerca do triplo do número circulante. A equivalência da alternativa B subestima essa reserva.","dica":"Pense em vários contingentes de prontidão."},{"id":"Q06.07","tipo":"VF","enunciado":"A reserva medular normal de leucócitos representa suprimento aproximado de seis horas.","alternativas":{},"resposta":"Falso","justificativa":"A reserva corresponde a cerca de seis dias, e não horas.","dica":"É uma reserva de dias, não de horas."},{"id":"Q06.08","tipo":"DISSERTATIVA","enunciado":"Onde permanece a maior parte dos linfócitos antes de circular transitoriamente no sangue?","alternativas":{},"resposta":"Nos tecidos linfoides.","justificativa":"A maioria dos linfócitos fica armazenada nos tecidos linfoides; uma pequena fração transita pelo sangue.","dica":"Diferencie depósito de via de transporte."}]},{"numero":7,"id":"bloco-07","titulo":"Megacariócitos fragmentam-se em plaquetas","sensivel":false,"busca_imagens":"megacariócito formação de plaquetas","busca_videos":"trombopoese megacariócito plaquetas","texto":[{"t":"p","texto":"Como mostrado na Figura 33-1, os megacariócitos (célula 3) são também formados na medula óssea, onde se fragmentam; os pequenos fragmentos, conhecidos como plaquetas (ou trombócitos), passam para o sangue. Eles são muito importantes no desencadeamento da coagulação sanguínea."}],"imagens":[{"id":"bloco-07-a","arquivo":"bloco-07-a.jpg","largura":768,"altura":1376,"alt":"Bloco 7, imagem 1 de 1: CORTE · MEGACARIÓCITO · PRODUZ PLAQUETAS"}],"questoes":[{"id":"Q07.01","tipo":"DIRETA","enunciado":"Qual célula medular se fragmenta para formar plaquetas?","alternativas":{},"resposta":"Megacariócito.","justificativa":"Os megacariócitos se fragmentam na medula óssea, gerando plaquetas.","dica":"O precursor é uma célula grande."},{"id":"Q07.02","tipo":"MULTIPLA","enunciado":"Qual sequência descreve corretamente a origem e o destino das plaquetas?","alternativas":{"A":"Monócito → linfa → tecido conjuntivo.","B":"Linfócito → baço → sangue.","C":"Granulócito → baço → sangue arterial.","D":"Megacariócito → plaquetas → sangue."},"resposta":"D","justificativa":"O megacariócito medular libera fragmentos que passam ao sangue. A alternativa C confunde plaquetas com granulócitos e desloca a origem para o baço.","dica":"Identifique a célula que se fragmenta."},{"id":"Q07.03","tipo":"VF","enunciado":"Trombócitos são pequenos fragmentos de megacariócitos que alcançam o sangue.","alternativas":{},"resposta":"Verdadeiro","justificativa":"Trombócito é sinônimo de plaqueta, formada por fragmentação de megacariócitos.","dica":"Dois nomes para o mesmo fragmento."},{"id":"Q07.04","tipo":"DISSERTATIVA","enunciado":"Qual processo sanguíneo é desencadeado com participação importante das plaquetas?","alternativas":{},"resposta":"Coagulação sanguínea.","justificativa":"As plaquetas participam do desencadeamento da coagulação sanguínea.","dica":"Relacione plaquetas à hemostasia."}]},{"numero":8,"id":"bloco-08","titulo":"Tempo de vida dos granulócitos e dos monócitos","sensivel":false,"busca_imagens":"monócito macrófago diferenciação tecido","busca_videos":"vida média dos granulócitos e monócitos","texto":[{"t":"h","texto":"Tempo deVida dos Leucócitos"},{"t":"p","texto":"A vida dos granulócitos, após sua liberação pela medula óssea, é normalmente de 4 a 8 horas circulando pelo sangue, e de mais 4 a 5 dias nos tecidos onde são necessários. Durante as infecções graves, essa duração total da vida dos leucócitos em geral se encurta para algumas horas, porque os granulócitos se dirigem com rapidez ainda maior para a área infectada para exercerem suas funções e, no processo, serem destruídos."},{"t":"p","texto":"Os monócitos têm também curto tempo de trânsito, de 10 a 20 horas no sangue, antes de atravessar as membranas capilares em direção aos tecidos. Uma vez nos tecidos, essas células aumentam seu volume para se transformar em macrófagos teciduais e, nessa forma, podem viver por meses, a menos que sejam destruídos durante a execução de suas funções fagocíticas. Os macrófagos teciduais são a base do sistema dos macrófagos teciduais, discutido em maiores detalhes adiante, que é responsável pela defesa contínua contra as infecções."}],"imagens":[{"id":"bloco-08-a","arquivo":"bloco-08-a.jpg","largura":768,"altura":1376,"alt":"Bloco 8, imagem 1 de 2: INFECÇÃO · GRANULÓCITO · DEFENDE O TECIDO"},{"id":"bloco-08-b","arquivo":"bloco-08-b.jpg","largura":768,"altura":1376,"alt":"Bloco 8, imagem 2 de 2: INFLAMAÇÃO · MONÓCITO · VIRA MACRÓFAGO"}],"questoes":[{"id":"Q08.01","tipo":"DIRETA","enunciado":"Por quanto tempo os granulócitos normalmente circulam no sangue após a liberação medular?","alternativas":{},"resposta":"4 a 8 horas.","justificativa":"Esse é o intervalo normal para a fase sanguínea dos granulócitos.","dica":"A circulação dura horas."},{"id":"Q08.02","tipo":"DIRETA","enunciado":"Por quanto tempo os granulócitos normalmente permanecem nos tecidos?","alternativas":{},"resposta":"4 a 5 dias.","justificativa":"Após circular, eles vivem por mais quatro a cinco dias nos tecidos onde são necessários.","dica":"A fase tecidual dura dias."},{"id":"Q08.03","tipo":"MULTIPLA","enunciado":"Em infecções graves, o que tende a ocorrer com a vida total dos granulócitos?","alternativas":{"A":"Cai para algumas horas.","B":"Cresce para vários dias.","C":"Mantém duração habitual.","D":"Estende-se por meses."},"resposta":"A","justificativa":"O recrutamento rápido à área infectada e a destruição durante a função encurtam a vida a horas. A alternativa B contraria essa aceleração do consumo.","dica":"Pense no consumo durante a resposta intensa."},{"id":"Q08.04","tipo":"VF","enunciado":"O trânsito dos monócitos no sangue antes da passagem para os tecidos dura normalmente quatro a oito horas.","alternativas":{},"resposta":"Falso","justificativa":"Monócitos circulam por 10 a 20 horas; quatro a oito horas é o intervalo sanguíneo dos granulócitos.","dica":"É mais longo que parte da fase sanguínea granulocítica."},{"id":"Q08.05","tipo":"DISSERTATIVA","enunciado":"Em que célula o monócito se transforma após atravessar o capilar e aumentar de volume no tecido?","alternativas":{},"resposta":"Macrófago tecidual.","justificativa":"Nos tecidos, os monócitos aumentam de volume e assumem a forma de macrófagos.","dica":"O nome remete à fagocitose tecidual."},{"id":"Q08.06","tipo":"VF","enunciado":"Macrófagos teciduais podem sobreviver por meses, desde que não sejam destruídos durante a fagocitose.","alternativas":{},"resposta":"Verdadeiro","justificativa":"Essa longevidade sustenta a defesa contínua contra infecções.","dica":"Compare sua permanência com a dos granulócitos."},{"id":"Q08.07","tipo":"DISSERTATIVA","enunciado":"Qual população celular constitui a base da defesa contínua contra infecções?","alternativas":{},"resposta":"Macrófagos teciduais.","justificativa":"A permanência prolongada dos macrófagos nos tecidos fundamenta essa defesa.","dica":"Procure a célula de longa duração."}]},{"numero":9,"id":"bloco-09","titulo":"Linfócitos recirculam; plaquetas são renovadas","sensivel":false,"busca_imagens":"recirculação de linfócitos linfonodo","busca_videos":"recirculação linfocitária e vida das plaquetas","texto":[{"t":"p","texto":"Os linfócitos entram de forma contínua no sistema circulatório, junto com a drenagem da linfa dos linfonodos e de outros tecidos linfoides. Depois de algumas Os Leucócitos se Movem pelos EspaçosTeciduais"},{"t":"leg","texto":"Figura 33-2 Movimento dos neutrófilos por diapedese pelos poros capilares e por quimiotaxia, pela área da lesão tecidual."},{"t":"p","texto":"horas, passam do sangue de volta para os tecidos por diapedese. Então, passado algum tempo, eles reentram na linfa e retornam várias vezes para o sangue; assim, existe circulação contínua de linfócitos por todo o corpo. Os linfócitos têm sobrevida que varia de semanas a meses, dependendo da necessidade pelo corpo dessas células."},{"t":"p","texto":"As plaquetas no sangue são substituídas a cada 10 dias; em outras palavras, aproximadamente 30.000 plaquetas são formadas a cada dia para cada microlitro de sangue."}],"imagens":[{"id":"bloco-09-a","arquivo":"bloco-09-a.jpg","largura":768,"altura":1376,"alt":"Bloco 9, imagem 1 de 3: CIRCULAÇÃO · LINFÓCITO · RECIRCULA PELO CORPO"},{"id":"bloco-09-b","arquivo":"bloco-09-b.jpg","largura":768,"altura":1376,"alt":"Bloco 9, imagem 2 de 3: CIRCULAÇÃO · NEUTRÓFILO · MIGRA AO FOCO"},{"id":"bloco-09-c","arquivo":"bloco-09-c.jpg","largura":768,"altura":1376,"alt":"Bloco 9, imagem 3 de 3: RENOVAÇÃO · PLAQUETAS · INICIAM COAGULAÇÃO"}],"questoes":[{"id":"Q09.01","tipo":"DIRETA","enunciado":"Por qual processo os linfócitos retornam do sangue aos tecidos após algumas horas?","alternativas":{},"resposta":"Diapedese.","justificativa":"A passagem do sangue para os tecidos ocorre por diapedese.","dica":"É a travessia da parede vascular."},{"id":"Q09.02","tipo":"MULTIPLA","enunciado":"Qual trajeto resume a recirculação dos linfócitos?","alternativas":{"A":"Medula → baço → urina → sangue.","B":"Sangue → rim → linfa → medula.","C":"Linfa → sangue → tecidos → linfa.","D":"Tecido → bile → sangue → tecido linfático."},"resposta":"C","justificativa":"Linfócitos chegam ao sangue pela drenagem linfática, entram nos tecidos e retornam à linfa. A alternativa B inclui o rim, que não participa desse circuito.","dica":"O circuito fecha pela drenagem linfática."},{"id":"Q09.03","tipo":"VF","enunciado":"A sobrevida dos linfócitos pode variar de semanas a meses conforme a necessidade do corpo.","alternativas":{},"resposta":"Verdadeiro","justificativa":"Esse intervalo variável é explicitamente atribuído aos linfócitos.","dica":"A duração é maior que a das plaquetas."},{"id":"Q09.04","tipo":"DIRETA","enunciado":"Em quanto tempo as plaquetas sanguíneas são substituídas?","alternativas":{},"resposta":"10 dias.","justificativa":"O período de renovação plaquetária é de dez dias.","dica":"Pense em cerca de uma semana e meia."},{"id":"Q09.05","tipo":"DISSERTATIVA","enunciado":"Aproximadamente quantas plaquetas são formadas por dia para cada microlitro de sangue?","alternativas":{},"resposta":"30.000 plaquetas.","justificativa":"Essa produção diária corresponde à substituição do contingente plaquetário em dez dias.","dica":"É cerca de um décimo da contagem total."},{"id":"Q09.06","tipo":"VF","enunciado":"Linfócitos podem retornar repetidas vezes dos tecidos à linfa e depois ao sangue.","alternativas":{},"resposta":"Verdadeiro","justificativa":"O circuito se repete, mantendo circulação contínua dessas células pelo corpo.","dica":"Visualize um circuito fechado."}]},{"numero":10,"id":"bloco-10","titulo":"Neutrófilos e macrófagos: o monócito cresce ao entrar nos tecidos","sensivel":false,"busca_imagens":"monócito transformação em macrófago","busca_videos":"macrófago tecidual origem monócito","texto":[{"t":"h","texto":"Neutrófilos e Macrófagos Fazem a Defesa Contra as Infecções"},{"t":"p","texto":"São principalmente os neutrófilos e os macrófagos teciduais que atacam e destroem as bactérias, os vírus e outros agentes invasores. Os neutrófilos são células maduras que podem atacar e destruir bactérias, mesmo no sangue circulante. De modo inverso, os macrófagos teciduais começam sua vida como monócitos no sangue, os quais são células imaturas que, ainda no sangue, têm pouca capacidade de combater os agentes infecciosos. Entretanto, assim que essas células entram nos tecidos, elas começam a aumentar de volume — algumas vezes, seus diâmetros aumentam por cinco vezes — podendo atingir 60 a 80 micrômetros, tamanho que pode ser visto a olho nu. Essas células são agora denominadas macrófagos e são extremamente capazes de combater os agentes patológicos intrateciduais."}],"imagens":[{"id":"bloco-10-a","arquivo":"bloco-10-a.jpg","largura":768,"altura":1376,"alt":"Bloco 10, imagem 1 de 2: INFECÇÃO · NEUTRÓFILO · ATACA NO SANGUE"},{"id":"bloco-10-b","arquivo":"bloco-10-b.jpg","largura":768,"altura":1376,"alt":"Bloco 10, imagem 2 de 2: INFECÇÃO · MACRÓFAGO · DEFENDE O TECIDO"}],"questoes":[{"id":"Q10.01","tipo":"DIRETA","enunciado":"Qual célula sanguínea madura pode destruir bactérias mesmo na circulação?","alternativas":{},"resposta":"Neutrófilo.","justificativa":"Neutrófilos já são maduros e atuam até no sangue circulante.","dica":"Compare com o precursor do macrófago."},{"id":"Q10.02","tipo":"MULTIPLA","enunciado":"Qual par de células é o principal responsável pelo ataque e destruição de agentes invasores?","alternativas":{"A":"Linfócitos e plasmócitos imunizados.","B":"Neutrófilos e macrófagos.","C":"Basófilos e plaquetas.","D":"Monócitos e hemácias."},"resposta":"B","justificativa":"Neutrófilos e macrófagos teciduais são os principais efetores. Linfócitos e plasmócitos pertencem a outra via defensiva.","dica":"São os dois grandes fagócitos deste trecho."},{"id":"Q10.03","tipo":"VF","enunciado":"Monócitos ainda circulantes já têm a mesma grande capacidade de combate dos macrófagos teciduais.","alternativas":{},"resposta":"Falso","justificativa":"No sangue, os monócitos são imaturos e têm pouca capacidade de combate; a capacidade aumenta após entrada nos tecidos.","dica":"Pense na maturação tecidual."},{"id":"Q10.04","tipo":"DISSERTATIVA","enunciado":"Até quantas vezes pode aumentar o diâmetro do monócito após sua entrada nos tecidos?","alternativas":{},"resposta":"Até cinco vezes.","justificativa":"O aumento de diâmetro pode chegar a cinco vezes na transformação em macrófago.","dica":"O crescimento é múltiplo, não discreto."},{"id":"Q10.05","tipo":"DIRETA","enunciado":"Qual faixa de diâmetro pode ser atingida pelo macrófago tecidual?","alternativas":{},"resposta":"60 a 80 µm.","justificativa":"Essa faixa corresponde a macrófagos após o aumento de volume tecidual.","dica":"São dezenas de micrômetros."},{"id":"Q10.06","tipo":"VF","enunciado":"O aumento dos monócitos ao entrar nos tecidos acompanha sua transformação em macrófagos capazes de combater agentes intrateciduais.","alternativas":{},"resposta":"Verdadeiro","justificativa":"A mudança de tamanho e identidade celular se associa ao ganho de capacidade defensiva no tecido.","dica":"Ligue transformação e função."}]},{"numero":11,"id":"bloco-11","titulo":"Diapedese e movimento ameboide","sensivel":false,"busca_imagens":"diapedese neutrófilo extravasamento leucocitário","busca_videos":"diapedese leucocitária e movimento ameboide","texto":[{"t":"p","texto":"Os Leucócitos Entram nos Espaços Teciduais por Diapedese. Os neutrófilos e os monócitos podem se espremer através dos poros dos capilares sanguíneos por diapedese. Ou seja, mesmo que um poro seja muito menor do que a célula, pequena porção da célula desliza pelo poro a cada vez; a porção que desliza pelo poro fica momentaneamente limitada ao tamanho do poro, como mostrado nas Figuras 33-2 e 33-6. por Movimento Ameboide. Os neutrófilos e os macrófagos podem se deslocar através dos tecidos por movimento ameboide, descrito no Capítulo 2. Algumas células se movem com velocidade de até 40 pm/min, distância correspondente a seu comprimento a cada minuto."}],"imagens":[{"id":"bloco-11-a","arquivo":"bloco-11-a.jpg","largura":768,"altura":1376,"alt":"Bloco 11, imagem 1 de 2: INFLAMAÇÃO · DIAPEDESE · LEVA LEUCÓCITOS AO TECIDO"},{"id":"bloco-11-b","arquivo":"bloco-11-b.jpg","largura":768,"altura":1376,"alt":"Bloco 11, imagem 2 de 2: FOCO INFLAMADO · MOVIMENTO AMEBOIDE · DESLOCA FAGÓCITOS"}],"questoes":[{"id":"Q11.01","tipo":"DIRETA","enunciado":"Como se chama a passagem de leucócitos pelos poros capilares até os tecidos?","alternativas":{},"resposta":"Diapedese.","justificativa":"Neutrófilos e monócitos atravessam os poros capilares por esse processo.","dica":"É a saída da circulação."},{"id":"Q11.02","tipo":"MULTIPLA","enunciado":"Como um leucócito atravessa um poro capilar menor que seu diâmetro?","alternativas":{"A":"Dissolve a parede vascular local.","B":"Fragmenta-se em vesículas.","C":"Reduz todo o seu diâmetro.","D":"Desliza em pequenas porções."},"resposta":"D","justificativa":"Pequenas porções da célula passam sucessivamente pelo poro e assumem temporariamente seu tamanho. A alternativa C sugere redução global da célula, mas a travessia ocorre por porções.","dica":"Imagine uma passagem gradual."},{"id":"Q11.03","tipo":"VF","enunciado":"Neutrófilos e monócitos podem passar dos capilares para os tecidos por diapedese.","alternativas":{},"resposta":"Verdadeiro","justificativa":"Ambas as populações são nomeadas como capazes dessa travessia.","dica":"Inclua o precursor dos macrófagos."},{"id":"Q11.04","tipo":"DIRETA","enunciado":"Qual tipo de movimento permite o deslocamento de neutrófilos e macrófagos através dos tecidos?","alternativas":{},"resposta":"Movimento ameboide.","justificativa":"O deslocamento tecidual dessas células é ameboide.","dica":"O termo remete à mudança de forma."},{"id":"Q11.05","tipo":"DISSERTATIVA","enunciado":"Qual velocidade máxima aproximada pode atingir o deslocamento ameboide?","alternativas":{},"resposta":"Até 40 µm/min.","justificativa":"O valor corresponde aproximadamente ao comprimento da célula percorrido por minuto; a unidade no original apresenta erro de OCR evidente.","dica":"São dezenas de micrômetros por minuto."},{"id":"Q11.06","tipo":"VF","enunciado":"Algumas dessas células podem percorrer aproximadamente o próprio comprimento a cada minuto.","alternativas":{},"resposta":"Verdadeiro","justificativa":"Essa equivalência acompanha a velocidade máxima para o movimento ameboide.","dica":"Use a dimensão celular como referência."}]},{"numero":12,"id":"bloco-12","titulo":"Quimiotaxia: fontes do sinal e gradiente de concentração","sensivel":false,"busca_imagens":"quimiotaxia neutrófilo gradiente quimiotático","busca_videos":"quimiotaxia dos leucócitos","texto":[{"t":"p","subtitulo":"Os Leucócitos São Atraídos para as Áreas do","texto":"Tecido Inflamado por Quimiotaxia. Várias substâncias químicas diferentes nos tecidos fazem com que os neutrófilos e macrófagos se movam na direção da fonte desta substância. Esse fenômeno, mostrado na Figura 33-2, é designado como quimiotaxia. Quando o tecido fica inflamado, é formada pelo menos uma dúzia de diferentes produtos que causam quimiotaxia na direção da área inflamada. Essas substâncias incluem (1) algumas das toxinas bacterianas e virais, (2) produtos degenerativos dos tecidos inflamados propriamente ditos, (3) vários produtos das reações do “complexo do complemento” (discutido no Cap. 34) ativado nos tecidos inflamados e (4) vários produtos das reações causadas pela coagulação sanguínea na área inflamada, bem como outras substâncias."},{"t":"p","texto":"Como mostrado na Figura 33-2, a quimiotaxia depende do gradiente de concentração da substância quimiotáxica. A concentração é maior próximo à sua fonte, o que determina o movimento unidirecional dos leucócitos. A quimiotaxia age por distâncias de até 100 micrômetros do tecido inflamado. Por conseguinte, como nenhuma área tecidual está à distância acima de 50 micrômetros de um capilar, o sinal quimiotáxico pode promover com facilidade o deslocamento de hordas de leucócitos dos capilares para a área inflamada."}],"imagens":[{"id":"bloco-12-a","arquivo":"bloco-12-a.jpg","largura":768,"altura":1376,"alt":"Bloco 12, imagem 1 de 2: SINAIS QUÍMICOS · QUIMIOTAXIA · ATRAI FAGÓCITOS"},{"id":"bloco-12-b","arquivo":"bloco-12-b.jpg","largura":768,"altura":1376,"alt":"Bloco 12, imagem 2 de 2: GRADIENTE · GRADIENTE QUÍMICO · ORIENTA LEUCÓCITOS"}],"questoes":[{"id":"Q12.01","tipo":"DIRETA","enunciado":"Como se chama o movimento de leucócitos em direção à fonte de substâncias químicas teciduais?","alternativas":{},"resposta":"Quimiotaxia.","justificativa":"O movimento dirigido de neutrófilos e macrófagos à fonte química recebe esse nome.","dica":"A direção depende de um sinal químico."},{"id":"Q12.02","tipo":"MULTIPLA","enunciado":"Qual fator determina a direção da quimiotaxia?","alternativas":{"A":"Gradiente de concentração química.","B":"Pressão venosa capilar no foco local.","C":"Tamanho dos grânulos celulares.","D":"Número de hemácias circulantes."},"resposta":"A","justificativa":"A maior concentração próxima à fonte estabelece o movimento unidirecional. A pressão capilar não é apontada como determinante dessa direção.","dica":"Siga a concentração crescente."},{"id":"Q12.03","tipo":"VF","enunciado":"O tecido inflamado forma pelo menos uma dúzia de produtos capazes de causar quimiotaxia.","alternativas":{},"resposta":"Verdadeiro","justificativa":"O tecido inflamado forma pelo menos doze produtos quimiotáticos distintos.","dica":"Há vários sinais, não um único mediador."},{"id":"Q12.04","tipo":"DISSERTATIVA","enunciado":"Cite quatro classes de produtos capazes de atrair neutrófilos e macrófagos à área inflamada.","alternativas":{},"resposta":"Toxinas bacterianas ou virais, produtos degenerativos teciduais, produtos do complemento e produtos da coagulação.","justificativa":"Essas quatro classes são explicitamente enumeradas como fontes de quimiotaxia.","dica":"Pense em agente, lesão e duas cascatas plasmáticas."},{"id":"Q12.05","tipo":"MULTIPLA","enunciado":"Assinale a exceção entre as fontes de produtos quimiotáticos da área inflamada.","alternativas":{"A":"Toxinas bacterianas.","B":"Degeneração tecidual.","C":"Reações do complemento local.","D":"Síntese de hemoglobina."},"resposta":"D","justificativa":"Síntese de hemoglobina não é uma fonte enumerada. A degeneração tecidual libera produtos que atraem leucócitos e é um distrator plausível.","dica":"Três opções se relacionam à inflamação."},{"id":"Q12.06","tipo":"DIRETA","enunciado":"Até que distância do tecido inflamado pode atuar o sinal quimiotático?","alternativas":{},"resposta":"100 µm.","justificativa":"A ação da quimiotaxia alcança até 100 micrômetros.","dica":"É o dobro da distância capilar máxima informada."},{"id":"Q12.07","tipo":"VF","enunciado":"Nenhuma área tecidual se situa a mais de 50 µm de um capilar.","alternativas":{},"resposta":"Verdadeiro","justificativa":"Essa proximidade facilita o deslocamento de leucócitos dos capilares para o foco inflamado.","dica":"Compare a distância capilar com o alcance do sinal."},{"id":"Q12.08","tipo":"DISSERTATIVA","enunciado":"Por que o sinal quimiotático consegue recrutar facilmente leucócitos capilares para áreas inflamadas?","alternativas":{},"resposta":"Seu alcance de 100 µm supera os 50 µm até um capilar.","justificativa":"A relação entre essas distâncias permite que o sinal alcance os leucócitos nos capilares próximos.","dica":"Compare dois valores em micrômetros."},{"id":"Q12.09","tipo":"MULTIPLA","enunciado":"Assinale as duas afirmações corretas. I. Toxinas virais podem gerar quimiotaxia. II. A concentração do sinal é menor perto da fonte. III. Produtos do complemento podem atrair leucócitos. IV. O alcance quimiotático fica restrito a 10 µm.","alternativas":{"A":"I e II.","B":"II e IV.","C":"I e III.","D":"III e IV."},"resposta":"C","justificativa":"I e III estão corretas: toxinas virais e produtos do complemento figuram entre os sinais quimiotáticos. II inverte o gradiente, cuja concentração é maior junto à fonte; IV reduz indevidamente o alcance de 100 µm.","dica":"Confira origem dos sinais e direção do gradiente."}]},{"numero":13,"id":"bloco-13","titulo":"Fagocitose: seletividade (superfície e revestimento)","sensivel":false,"busca_imagens":"fagocitose macrófago bactéria microscopia","busca_videos":"fagocitose seletividade reconhecimento","texto":[{"t":"h","texto":"Fagocitose"},{"t":"p","texto":"A função mais importante dos neutrófilos e dos macrófagos é a fagocitose, que significa ingestão celular do agente agressor. Os fagócitos devem ser seletivos quanto ao material que é fagocitado; caso contrário, células e estruturas normais do corpo poderíam ser ingeridas. A ocorrência de fagocitose depende de três procedimentos seletivos."},{"t":"p","texto":"Primeiro, a maioria das estruturas naturais nos tecidos tem superfícies lisas que resistem à fagocitose. Mas, se a superfície é áspera, a probabilidade de fagocitose aumenta."},{"t":"p","texto":"Segundo, a maioria das substâncias naturais do corpo tem revestimentos proteicos protetores que repelem os fagócitos. De forma inversa, a maioria dos tecidos mortos e das partículas estranhas ao corpo não apresenta esse revestimento protetor, o que os faz sujeitos à fagocitose."}],"imagens":[{"id":"bloco-13-a","arquivo":"bloco-13-a.jpg","largura":768,"altura":1376,"alt":"Bloco 13, imagem 1 de 2: PARTÍCULA ESTRANHA · FAGOCITOSE · INGERE ALVOS ESTRANHOS"},{"id":"bloco-13-b","arquivo":"bloco-13-b.jpg","largura":768,"altura":1376,"alt":"Bloco 13, imagem 2 de 2: PARTÍCULA ESTRANHA · SELETIVIDADE · POUPA CÉLULAS NORMAIS"}],"questoes":[{"id":"Q13.01","tipo":"DIRETA","enunciado":"Qual é a principal função dos neutrófilos e macrófagos?","alternativas":{},"resposta":"Fagocitose.","justificativa":"A ingestão celular do agente agressor é sua função mais importante.","dica":"O fagócito engole o alvo."},{"id":"Q13.02","tipo":"MULTIPLA","enunciado":"Qual característica superficial aumenta a probabilidade de fagocitose?","alternativas":{"A":"Revestimento proteico preservado.","B":"Superfície celular lisa.","C":"Superfície irregular áspera.","D":"Membrana natural intacta."},"resposta":"C","justificativa":"A superfície áspera favorece a fagocitose. A superfície lisa, opção tentadora, resiste a ela.","dica":"Compare aspereza com lisura."},{"id":"Q13.03","tipo":"VF","enunciado":"A seletividade fagocítica evita a ingestão indiscriminada de células e estruturas normais do corpo.","alternativas":{},"resposta":"Verdadeiro","justificativa":"Sem seletividade, os fagócitos poderiam ingerir componentes próprios normais.","dica":"Reconhecer o alvo protege o tecido íntegro."},{"id":"Q13.04","tipo":"DISSERTATIVA","enunciado":"Qual efeito do revestimento proteico protetor das substâncias naturais do corpo sobre os fagócitos?","alternativas":{},"resposta":"Repele os fagócitos.","justificativa":"O revestimento reduz a suscetibilidade dos componentes próprios à fagocitose.","dica":"Pense em proteção da superfície."},{"id":"Q13.05","tipo":"VF","enunciado":"Tecidos mortos e partículas estranhas frequentemente carecem do revestimento proteico protetor e ficam sujeitos à fagocitose.","alternativas":{},"resposta":"Verdadeiro","justificativa":"A ausência desse revestimento os torna alvos mais fáceis para os fagócitos.","dica":"Compare superfícies próprias preservadas e alvos alterados."},{"id":"Q13.06","tipo":"DISSERTATIVA","enunciado":"Quais duas propriedades da superfície do alvo influenciam a seleção fagocítica?","alternativas":{},"resposta":"Aspereza e presença de revestimento proteico protetor.","justificativa":"A superfície áspera favorece a ingestão, enquanto o revestimento proteico a dificulta.","dica":"Avalie textura e cobertura."}]},{"numero":14,"id":"bloco-14","titulo":"Opsonização: anticorpo, C3 e receptor do fagócito","sensivel":false,"busca_imagens":"opsonização anticorpo C3b fagócito","busca_videos":"opsonização fagocitose complemento","texto":[{"t":"p","texto":"Terceiro, o sistema imune do corpo (descrito em detalhes no Cap. 34) desenvolve anticorpos contra os agentes infecciosos, como as bactérias. Os anticorpos aderem às membranas bacterianas tornando-as especialmente suscetíveis à fagocitose. Para isso, a molécula do anticorpo também se combina com o produto C3 da cascata de complemento, que é a parte adicional do sistema imune, discutida no próximo capítulo. As moléculas C3 por sua vez se prendem a receptores da membrana do fagócito, iniciando o processo de fagocitose. Esse processo de seleção e de fagocitose é referido como opsonização."}],"imagens":[{"id":"bloco-14-a","arquivo":"bloco-14-a.jpg","largura":768,"altura":1376,"alt":"Bloco 14, imagem 1 de 1: BACTÉRIA · OPSONIZAÇÃO · FACILITA FAGOCITOSE"}],"questoes":[{"id":"Q14.01","tipo":"DIRETA","enunciado":"Como se chama a seleção e ingestão facilitada por anticorpo e complemento?","alternativas":{},"resposta":"Opsonização.","justificativa":"Esse é o nome dado ao processo de marcação do agente infeccioso e início da fagocitose.","dica":"Pense na marcação do invasor."},{"id":"Q14.02","tipo":"MULTIPLA","enunciado":"Qual componente do complemento se associa ao anticorpo aderido à bactéria durante a opsonização?","alternativas":{"A":"C1q plasmático.","B":"C3 do complemento.","C":"C4b do complemento.","D":"C5a do complemento."},"resposta":"B","justificativa":"O anticorpo se combina com C3, que se liga ao receptor do fagócito. C4b também pertence ao complemento, mas não é o produto indicado nessa ligação.","dica":"É identificado por uma letra e um número."},{"id":"Q14.03","tipo":"VF","enunciado":"Anticorpos aderidos à membrana bacteriana tornam a bactéria mais suscetível à fagocitose.","alternativas":{},"resposta":"Verdadeiro","justificativa":"A aderência do anticorpo à bactéria é a etapa inicial da facilitação fagocítica.","dica":"A marcação precede o reconhecimento."},{"id":"Q14.04","tipo":"DISSERTATIVA","enunciado":"A que estrutura se prendem as moléculas de C3 para iniciar a fagocitose?","alternativas":{},"resposta":"Receptores da membrana do fagócito.","justificativa":"C3 faz a ligação entre o anticorpo associado à bactéria e os receptores fagocíticos.","dica":"Procure o ponto de contato na célula que engole."},{"id":"Q14.05","tipo":"VF","enunciado":"Na opsonização, C3 liga-se ao receptor do fagócito antes de o anticorpo aderir à bactéria.","alternativas":{},"resposta":"Falso","justificativa":"Primeiro o anticorpo adere à membrana bacteriana, depois combina-se com C3, que se liga ao receptor fagocítico.","dica":"Ordene marcação e ligação ao complemento."},{"id":"Q14.06","tipo":"DISSERTATIVA","enunciado":"Resuma a sequência molecular da opsonização.","alternativas":{},"resposta":"Anticorpo adere à bactéria, combina-se com C3, e C3 liga-se ao receptor do fagócito.","justificativa":"Essa cadeia de ligações inicia o processo de fagocitose do agente marcado.","dica":"Siga o caminho do invasor até o fagócito."}]},{"numero":15,"id":"bloco-15","titulo":"Fagocitose pelos neutrófilos","sensivel":false,"busca_imagens":"fagocitose neutrófilo fagossomo pseudópodes","busca_videos":"fagocitose etapas neutrófilo","texto":[{"t":"p","texto":"A Fagocitose pelos Neutrófilos. Os neutrófilos que penetram nos tecidos já são células maduras, capazes de iniciar imediatamente a fagocitose. Ao se aproximar da partícula a ser fagocitada, o neutrófilo primeiro se prende à partícula, e, em seguida, emite pseudópodos em todas as direções ao redor da partícula. Os pseudópodos se encontram no outro lado e se fundem. Isso cria uma câmara fechada contendo a partícula fagocitada. A seguir, a câmara se invagina para a cavidade citoplasmática e rompe suas conexões com a membrana externa da célula, para formar vesícula fagocítica (também chamada de fagossoma) que flutua livremente no citoplasma. Um só neutrófilo pode, em geral, fagocitar cerca de três a 20 bactérias, antes de ser inativado e morrer."}],"imagens":[{"id":"bloco-15-a","arquivo":"bloco-15-a.jpg","largura":768,"altura":1376,"alt":"Bloco 15, imagem 1 de 2: BACTÉRIA · NEUTRÓFILO · ENGLOBA BACTÉRIAS"},{"id":"bloco-15-b","arquivo":"bloco-15-b.jpg","largura":768,"altura":1376,"alt":"Bloco 15, imagem 2 de 2: BACTÉRIA · NEUTRÓFILO · FAGOCITA 3–20 BACTÉRIAS"}],"questoes":[{"id":"Q15.01","tipo":"DIRETA","enunciado":"Que projeções o neutrófilo emite para envolver uma partícula aderida?","alternativas":{},"resposta":"Pseudópodos.","justificativa":"O neutrófilo projeta pseudópodos ao redor da partícula antes de formar a câmara fechada.","dica":"São extensões transitórias da célula."},{"id":"Q15.02","tipo":"MULTIPLA","enunciado":"Qual evento ocorre imediatamente após os pseudópodos se encontrarem e se fundirem ao redor da partícula?","alternativas":{"A":"Produção de anticorpos circulantes.","B":"Liberação de plaquetas no sangue.","C":"Retorno à medula.","D":"Formação de uma câmara fechada."},"resposta":"D","justificativa":"A fusão dos pseudópodos fecha uma câmara com a partícula. A formação de anticorpos pertence a outra via de defesa.","dica":"Pense no fechamento do invólucro."},{"id":"Q15.03","tipo":"VF","enunciado":"Neutrófilos que penetram nos tecidos já são maduros e podem iniciar prontamente a fagocitose.","alternativas":{},"resposta":"Verdadeiro","justificativa":"A maturidade antecede a entrada tecidual, permitindo ação imediata.","dica":"Compare com a maturação dos monócitos."},{"id":"Q15.04","tipo":"DISSERTATIVA","enunciado":"Como se chama a vesícula formada quando a câmara com a partícula se separa da membrana externa?","alternativas":{},"resposta":"Fagossoma.","justificativa":"A câmara invagina e se desprende, formando a vesícula fagocítica livre no citoplasma.","dica":"O nome começa pelo processo de ingestão."},{"id":"Q15.05","tipo":"DIRETA","enunciado":"Quantas bactérias um neutrófilo geralmente pode fagocitar antes de ser inativado?","alternativas":{},"resposta":"3 a 20.","justificativa":"Esse é o intervalo normal antes da inativação e morte do neutrófilo.","dica":"É uma faixa de unidades a dezenas."},{"id":"Q15.06","tipo":"VF","enunciado":"Um neutrófilo geralmente fagocita até 100 bactérias antes de ser inativado e morrer.","alternativas":{},"resposta":"Falso","justificativa":"O neutrófilo geralmente fagocita de três a vinte bactérias antes de ser inativado.","dica":"Relacione consumo e fim da atividade."},{"id":"Q15.07","tipo":"DISSERTATIVA","enunciado":"Qual a ordem dos eventos entre aderência do neutrófilo à partícula e formação do fagossoma?","alternativas":{},"resposta":"Emissão e fusão de pseudópodos, fechamento da câmara, invaginação e separação da membrana externa.","justificativa":"Essa sequência gera uma vesícula fagocítica livre no citoplasma.","dica":"Primeiro envolva; depois internalize."}]},{"numero":16,"id":"bloco-16","titulo":"Fagocitose pelos macrófagos","sensivel":false,"busca_imagens":"macrófago fagocitando hemácia","busca_videos":"macrófago versus neutrófilo fagocitose","texto":[{"t":"p","texto":"A Fagocitose pelos Macrófagos. Os macrófagos são o produto final dos monócitos que penetram nos tecidos vindos do sangue. Quando ativados pelo sistema imune, como descrito no Capítulo 34, eles são fagócitos muito mais potentes que os neutrófilos, capazes, em geral, de fagocitar até 100 bactérias. Têm também a capacidade de envolver partículas muito maiores, até mesmo hemácias inteiras ou, ocasionalmente, parasitas da malária, enquanto os neutrófilos não são capazes de fagocitar partículas muito maiores do que bactérias. Além disso, após a digestão das partículas, os macrófagos podem eliminar os produtos residuais e, com frequência, sobrevivem e funcionam por muitos mais meses."}],"imagens":[{"id":"bloco-16-a","arquivo":"bloco-16-a.jpg","largura":768,"altura":1376,"alt":"Bloco 16, imagem 1 de 2: INVASOR · MACRÓFAGO · ENGLOBA ALVOS GRANDES"},{"id":"bloco-16-b","arquivo":"bloco-16-b.jpg","largura":768,"altura":1376,"alt":"Bloco 16, imagem 2 de 2: INVASOR · MACRÓFAGO · REMOVE E CONTINUA ATIVO"}],"questoes":[{"id":"Q16.01","tipo":"DIRETA","enunciado":"De qual célula sanguínea se originam os macrófagos teciduais?","alternativas":{},"resposta":"Monócito.","justificativa":"Macrófagos são o produto final de monócitos que atravessam do sangue para os tecidos.","dica":"Pense no precursor circulante."},{"id":"Q16.02","tipo":"MULTIPLA","enunciado":"Quantas bactérias pode fagocitar, em geral, um macrófago ativado pelo sistema imune?","alternativas":{"A":"Até 10 bactérias.","B":"Até 20 bactérias.","C":"Até 100 bactérias.","D":"Até 1.000 bactérias."},"resposta":"C","justificativa":"A capacidade do macrófago ativado chega a 100 bactérias. Até 20 é a faixa superior atribuída ao neutrófilo.","dica":"Supera a capacidade do neutrófilo."},{"id":"Q16.03","tipo":"VF","enunciado":"Macrófagos ativados podem envolver hemácias inteiras e, ocasionalmente, parasitas da malária.","alternativas":{},"resposta":"Verdadeiro","justificativa":"Essas partículas maiores exemplificam a capacidade de ingestão dos macrófagos.","dica":"Considere o tamanho do alvo."},{"id":"Q16.04","tipo":"DISSERTATIVA","enunciado":"Qual limitação de tamanho do alvo é atribuída aos neutrófilos em comparação com macrófagos?","alternativas":{},"resposta":"Não fagocitam partículas muito maiores que bactérias.","justificativa":"Macrófagos podem englobar partículas maiores, inclusive hemácias inteiras.","dica":"Compare a escala dos alvos ingeridos."},{"id":"Q16.05","tipo":"VF","enunciado":"Após a digestão, macrófagos podem eliminar resíduos e continuar funcionantes por muitos meses.","alternativas":{},"resposta":"Verdadeiro","justificativa":"O descarte de produtos residuais e a sobrevivência prolongada são diferenças funcionais em relação aos neutrófilos.","dica":"Pense em reutilização da célula."},{"id":"Q16.06","tipo":"DISSERTATIVA","enunciado":"Qual condição aumenta a potência fagocítica dos macrófagos?","alternativas":{},"resposta":"Ativação pelo sistema imune.","justificativa":"Essa ativação aumenta a capacidade de fagocitar mais bactérias e partículas maiores.","dica":"A mudança funcional depende de ativação."}]},{"numero":17,"id":"bloco-17","titulo":"Digestão intracelular: lisossomas e lipases","sensivel":false,"busca_imagens":"fagolisossomo lisossomo fusão","busca_videos":"fagolisossomo digestão intracelular","texto":[{"t":"p","texto":"Uma Vez Fagocitadas, a Maioria das Partículas É Digerida pelas Enzimas Intracelulares. Quando a partícula estranha é fagocitada, lisossomas e outros grânulos citoplasmáticos no neutrófilo ou no macrófago entram em contato imediatamente com a vesícula fagocítica e suas membranas se fundem, esvaziando muitas enzimas digestivas e agentes bactericidas nessa vesícula. Assim, a vesícula fagocítica passa a ser uma vesícula digestiva, e a digestão das partículas fagocitadas começa imediatamente."},{"t":"p","texto":"Os neutrófilos e os macrófagos contêm grande número de lisossomas repletos de enzimas proteolíticas, especificamente voltadas para a digestão de bactérias e de outras matérias proteicas estranhas. Os lisossomas dos macrófagos (mas não dos neutrófilos) contêm também grande quantidade de lipases, que digerem as espessas membranas lipídicas de bactérias como o bacilo da tuberculose."}],"imagens":[{"id":"bloco-17-a","arquivo":"bloco-17-a.jpg","largura":768,"altura":1376,"alt":"Bloco 17, imagem 1 de 2: PARTÍCULA CAPTURADA · LISOSSOMO · DIGERE O INVASOR"},{"id":"bloco-17-b","arquivo":"bloco-17-b.jpg","largura":768,"altura":1376,"alt":"Bloco 17, imagem 2 de 2: PARTÍCULA CAPTURADA · LIPASE · DIGERE LIPÍDIOS"}],"questoes":[{"id":"Q17.01","tipo":"DIRETA","enunciado":"Qual organela fornece grande parte das enzimas digestivas à vesícula fagocítica?","alternativas":{},"resposta":"Lisossoma.","justificativa":"Lisossomas fundem suas membranas à vesícula fagocítica e descarregam enzimas.","dica":"É o compartimento de digestão celular."},{"id":"Q17.02","tipo":"MULTIPLA","enunciado":"Qual evento transforma a vesícula fagocítica em vesícula digestiva?","alternativas":{"A":"Entrada de hemácias no citoplasma.","B":"Fusão com grânulos enzimáticos.","C":"Saída de C3 pela membrana.","D":"Divisão do núcleo fagocítico."},"resposta":"B","justificativa":"Lisossomas e outros grânulos fundem-se à vesícula e despejam enzimas e agentes bactericidas. A entrada de hemácias representa um possível alvo, não a etapa de digestão.","dica":"É preciso incorporar o conteúdo enzimático."},{"id":"Q17.03","tipo":"VF","enunciado":"A digestão de partículas fagocitadas pode começar imediatamente após a fusão da vesícula com lisossomas.","alternativas":{},"resposta":"Verdadeiro","justificativa":"A liberação de enzimas na vesícula inicia prontamente a digestão.","dica":"Relacione fusão e início da degradação."},{"id":"Q17.04","tipo":"DISSERTATIVA","enunciado":"Que classe de enzimas lisossômicas digere bactérias e outras matérias proteicas estranhas?","alternativas":{},"resposta":"Enzimas proteolíticas.","justificativa":"Tanto neutrófilos quanto macrófagos contêm lisossomas ricos nessas enzimas.","dica":"O substrato é proteína."},{"id":"Q17.05","tipo":"DIRETA","enunciado":"Qual enzima abundante nos lisossomas de macrófagos digere membranas lipídicas espessas?","alternativas":{},"resposta":"Lipase.","justificativa":"Lipases macrofágicas degradam membranas lipídicas, como as do bacilo da tuberculose.","dica":"O nome indica o substrato gorduroso."},{"id":"Q17.06","tipo":"VF","enunciado":"Lisossomas dos neutrófilos, mas não dos macrófagos, contêm grande quantidade de lipases contra membranas bacterianas lipídicas.","alternativas":{},"resposta":"Falso","justificativa":"A grande quantidade de lipases é atribuída aos lisossomas dos macrófagos, não aos dos neutrófilos.","dica":"Associe o recurso à ingestão de alvos difíceis."}]},{"numero":18,"id":"bloco-18","titulo":"Agentes bactericidas e bactérias resistentes","sensivel":false,"busca_imagens":"explosão respiratória neutrófilo mieloperoxidase","busca_videos":"explosão respiratória e mieloperoxidase","texto":[{"t":"p","texto":"Tanto os Neutrófilos Quanto os Macrófagos Podem Destruir Bactérias. Além da digestão das bactérias ingeridas nos fagossomas, os neutrófilos e macrófagos contêm agentes bactericidas que destroem a maioria das bactérias, mesmo quando as enzimas lisossômicas não conseguem digeri-las. Esse fato é especialmente impor tante, porque algumas bactérias têm revestimentos protetores ou outros fatores que impedem sua destruição pelas enzimas digestivas. Grande parte desse efeito mortal resulta de diversos agentes oxidantes potentes formados por enzimas nas membranas do fagossoma ou por organela especial chamada peroxissoma. Esses agentes oxidantes incluem grande quantidade de superóxido (Of) , peróxido de hidrogênio (H202) e íons hidroxila (OH\"), todos letais para a maioria das bactérias, mesmo em pequena quantidade. Além disso, uma das enzimas lisossômicas, a mieloperoxidase, catalisa a reação entre o H202 e os íons cloreto para formar hipoclorito, que é extremamente bactericida."},{"t":"p","texto":"Entretanto, algumas bactérias, notadamente o bacilo da tuberculose, têm revestimentos resistentes à digestão lisossômica e também secretam substâncias que resistem parcialmente aos efeitos dos neutrófilos e macrófagos. Essas bactérias são responsáveis por muitas doenças crônicas, como a tuberculose."}],"imagens":[{"id":"bloco-18-a","arquivo":"bloco-18-a.jpg","largura":768,"altura":1376,"alt":"Bloco 18, imagem 1 de 3: BACTÉRIA · OXIDANTES · DESTROEM BACTÉRIAS"},{"id":"bloco-18-b","arquivo":"bloco-18-b.jpg","largura":768,"altura":1376,"alt":"Bloco 18, imagem 2 de 3: BACTÉRIA · MIELOPEROXIDASE · FORMA HIPOCLORITO"},{"id":"bloco-18-c","arquivo":"bloco-18-c.jpg","largura":768,"altura":1376,"alt":"Bloco 18, imagem 3 de 3: BACILO · BACILO DA TUBERCULOSE · RESISTE À DESTRUIÇÃO"}],"questoes":[{"id":"Q18.01","tipo":"DIRETA","enunciado":"Qual enzima lisossômica catalisa a formação de hipoclorito?","alternativas":{},"resposta":"Mieloperoxidase.","justificativa":"A mieloperoxidase catalisa a reação de peróxido de hidrogênio com cloreto.","dica":"É uma peroxidase dos fagócitos."},{"id":"Q18.02","tipo":"MULTIPLA","enunciado":"Quais reagentes originam hipoclorito na reação catalisada pela mieloperoxidase?","alternativas":{"A":"Superóxido e serotonina.","B":"Hidroxila e fibrinogênio.","C":"Histamina e C3.","D":"Peróxido e íons cloreto."},"resposta":"D","justificativa":"Peróxido de hidrogênio e íons cloreto formam hipoclorito nessa reação. Superóxido também é bactericida, mas não é o par de reagentes especificado.","dica":"Pense em oxidante e haleto."},{"id":"Q18.03","tipo":"VF","enunciado":"Neutrófilos e macrófagos podem destruir bactérias mesmo quando as enzimas lisossômicas não conseguem digeri-las.","alternativas":{},"resposta":"Verdadeiro","justificativa":"Agentes bactericidas complementam a digestão enzimática, inclusive contra bactérias com revestimentos protetores.","dica":"Há mecanismos além da digestão."},{"id":"Q18.04","tipo":"DISSERTATIVA","enunciado":"Cite os três agentes oxidantes bactericidas enumerados.","alternativas":{},"resposta":"Superóxido, peróxido de hidrogênio e íons hidroxila.","justificativa":"Esses oxidantes são formados no sistema fagocítico e têm efeito letal sobre muitas bactérias.","dica":"Um radical de oxigênio, água oxigenada e hidroxila."},{"id":"Q18.05","tipo":"MULTIPLA","enunciado":"Qual combinação participa da formação de potentes oxidantes bactericidas nos fagócitos?","alternativas":{"A":"Lisossoma e núcleo.","B":"Fagossoma e peroxissoma.","C":"Fagossoma e membrana externa.","D":"Lisossoma e membrana bacteriana."},"resposta":"B","justificativa":"Enzimas da membrana do fagossoma e o peroxissoma formam esses oxidantes. O lisossoma contém enzimas digestivas e agentes bactericidas, mas não compõe a dupla de fontes oxidantes indicada.","dica":"Pense na vesícula de ingestão e em uma organela oxidativa."},{"id":"Q18.06","tipo":"VF","enunciado":"O bacilo da tuberculose pode resistir à digestão lisossômica por seu revestimento e por substâncias que secreta.","alternativas":{},"resposta":"Verdadeiro","justificativa":"Esses dois fatores contribuem para a resistência parcial às ações de neutrófilos e macrófagos.","dica":"Considere barreira externa e produto secretado."},{"id":"Q18.07","tipo":"DISSERTATIVA","enunciado":"Qual consequência clínica é associada à resistência de certas bactérias à ação dos fagócitos?","alternativas":{},"resposta":"Doenças crônicas, como tuberculose.","justificativa":"A persistência bacteriana é relacionada à cronicidade dessas doenças.","dica":"Pense na permanência do agente."}]},{"numero":19,"id":"bloco-19","titulo":"Sistema monocítico-macrofágico (reticuloendotelial)","sensivel":false,"busca_imagens":"sistema mononuclear fagocitário","busca_videos":"sistema reticuloendotelial macrófagos teciduais","texto":[{"t":"h","texto":"O Sistema Celular Monocítico-Macrofágico (Sistema Reticuloendotelial)"},{"t":"p","texto":"Nos parágrafos anteriores, descrevemos os macrófagos principalmente como células móveis que são capazes de se deslocar pelos tecidos. Entretanto, depois de entrarem nos tecidos e se transformarem em macrófagos, outra grande parte dos monócitos fica presa nos tecidos, lá permanecendo durante meses ou anos, até que seja mobilizada para realizar suas funções protetoras locais específicas. Eles têm as mesmas capacidades dos macrófagos móveis para fagocitar muitas bactérias, vírus, tecido necrótico ou outras partículas estranhas nos tecidos. E quando apropriadamente estimulados podem romper suas conexões e voltar a ser macrófagos móveis, capazes de responder à quimiotaxia e a todos os outros estímulos relacionados ao processo inflamatório. Assim, o corpo tem amplo “sistema monocítico-macrofágico” em praticamente todas as áreas teciduais."},{"t":"p","texto":"A combinação total de monócitos, macrófagos móveis e macrófagos teciduais fixos e algumas células endoteliais especializadas na medula óssea, no baço e nos linfonodos é referida como sistema reticuloendotelial. Entretanto, todas ou quase todas essas células são derivadas de células-tronco monocíticas; portanto, o sistema reticuloendotelial é quase sinônimo do sistema monocítico-macrofágico. Como o termo sistema reticuloendotelial é muito mais conhecido na literatura médica do que o sistema monocítico-macrofágico, ele deve ser lembrado como um sistema fagocítico generalizado presente em todos os tecidos, especialmente nas áreas teciduais onde grandes quantidades de partículas, toxinas e outras substâncias indesejáveis devem ser destruídas."}],"imagens":[{"id":"bloco-19-a","arquivo":"bloco-19-a.jpg","largura":768,"altura":1376,"alt":"Bloco 19, imagem 1 de 2: PARTÍCULAS · MACRÓFAGOS RESIDENTES · DEFENDEM TECIDOS"},{"id":"bloco-19-b","arquivo":"bloco-19-b.jpg","largura":768,"altura":1376,"alt":"Bloco 19, imagem 2 de 2: PARTÍCULAS · MONÓCITO · ORIGINA MACRÓFAGOS"}],"questoes":[{"id":"Q19.01","tipo":"DIRETA","enunciado":"Qual é o nome alternativo do sistema monocítico-macrofágico?","alternativas":{},"resposta":"Sistema reticuloendotelial.","justificativa":"Os termos são quase sinônimos para esse sistema fagocítico generalizado.","dica":"É a designação tradicional da literatura."},{"id":"Q19.02","tipo":"MULTIPLA","enunciado":"Por quanto tempo parte dos macrófagos pode permanecer fixa nos tecidos antes de mobilização?","alternativas":{"A":"Horas.","B":"Meses ou anos.","C":"Dois ou três dias.","D":"Uma ou duas semanas."},"resposta":"B","justificativa":"Parte dos monócitos transformados em macrófagos permanece presa nos tecidos por meses ou anos. Semanas subestimam essa permanência.","dica":"São células residentes duradouras."},{"id":"Q19.03","tipo":"VF","enunciado":"Quando estimulados, macrófagos teciduais fixos podem romper suas conexões e voltar a se deslocar por quimiotaxia.","alternativas":{},"resposta":"Verdadeiro","justificativa":"A mobilização restaura o comportamento de macrófagos móveis diante de estímulos inflamatórios.","dica":"A residência pode ser reversível."},{"id":"Q19.04","tipo":"DISSERTATIVA","enunciado":"Quais componentes celulares compõem o sistema reticuloendotelial ?","alternativas":{},"resposta":"Monócitos, macrófagos móveis, macrófagos fixos e algumas células endoteliais especializadas.","justificativa":"Essas populações formam o sistema fagocítico generalizado.","dica":"Reúna células circulantes, residentes e endoteliais."},{"id":"Q19.05","tipo":"MULTIPLA","enunciado":"Em quais três órgãos se encontram células endoteliais especializadas desse sistema?","alternativas":{"A":"Medula, baço e linfonodos.","B":"Timo, baço e tecido pancreático.","C":"Medula, fígado e coração.","D":"Pulmão, timo e linfonodos."},"resposta":"A","justificativa":"Medula óssea, baço e linfonodos são os órgãos que abrigam essas células endoteliais especializadas. O fígado não integra esse trio na definição do sistema.","dica":"Há dois órgãos que filtram sangue e linfa."},{"id":"Q19.06","tipo":"VF","enunciado":"Macrófagos fixos conservam capacidade de fagocitar bactérias, vírus, tecido necrótico e partículas estranhas.","alternativas":{},"resposta":"Verdadeiro","justificativa":"Suas capacidades fagocíticas são equivalentes às dos macrófagos móveis.","dica":"A fixação não elimina a função."},{"id":"Q19.07","tipo":"DISSERTATIVA","enunciado":"Em que áreas teciduais a ação do sistema reticuloendotelial é especialmente relevante?","alternativas":{},"resposta":"Nas áreas com muitas partículas, toxinas e substâncias indesejáveis a destruir.","justificativa":"O sistema fagocítico está disseminado, com papel destacado onde a carga de material indesejado é grande.","dica":"Pense em locais de filtragem."},{"id":"Q19.08","tipo":"DISSERTATIVA","enunciado":"Qual origem celular torna quase sinônimos os sistemas reticuloendotelial e monocítico-macrofágico?","alternativas":{},"resposta":"Células-tronco monocíticas.","justificativa":"Todas ou quase todas as células desses sistemas derivam dessa linhagem.","dica":"Procure a origem comum dos monócitos."}]},{"numero":20,"id":"bloco-20","titulo":"Macrófagos teciduais da pele e do subcutâneo (histiócitos)","sensivel":false,"busca_imagens":"histiócito macrófago tecido conjuntivo pele","busca_videos":"macrófagos teciduais pele histiócitos","texto":[{"t":"p","texto":"Macrófagos Teciduais na Pele e nos Tecidos Subcutâneos (Histiócitos). Apesar de a pele ser, em grande parte, impregnável aos agentes infecciosos, esse fato não é verdadeiro quando a integridade da pele é rompida. Quando a infecção se inicia no tecido subcutâneo e inflamação local se instala, os macrófagos teciduais locais podem se dividir in situ e formar novos macrófagos. Essas células podem realizar as funções usuais de ataque e destruição dos agentes infecciosos, como descrito antes."}],"imagens":[{"id":"bloco-20-a","arquivo":"bloco-20-a.jpg","largura":768,"altura":1376,"alt":"Bloco 20, imagem 1 de 1: ARRANHÃO · HISTIÓCITOS · FAGOCITAM MICRÓBIOS"}],"questoes":[{"id":"Q20.01","tipo":"DIRETA","enunciado":"Como são chamados os macrófagos teciduais da pele e do tecido subcutâneo?","alternativas":{},"resposta":"Histiócitos.","justificativa":"Histiócitos é a denominação dos macrófagos locais da pele e do subcutâneo.","dica":"O nome remete a tecido."},{"id":"Q20.02","tipo":"MULTIPLA","enunciado":"Qual evento permite que agentes infecciosos penetrem mais facilmente pela pele?","alternativas":{"A":"Aumento da linfa circulante.","B":"Recrutamento dos linfócitos.","C":"Ruptura da integridade cutânea.","D":"Divisão dos macrófagos residentes locais."},"resposta":"C","justificativa":"A barreira cutânea perde eficácia quando sua integridade é rompida. A divisão de macrófagos é resposta à infecção, não o evento que abre a via de entrada.","dica":"Considere a barreira física."},{"id":"Q20.03","tipo":"VF","enunciado":"Na infecção subcutânea com inflamação local, macrófagos residentes podem dividir-se no próprio tecido.","alternativas":{},"resposta":"Verdadeiro","justificativa":"A divisão in situ produz novos macrófagos locais.","dica":"A reposição pode ocorrer no local."},{"id":"Q20.04","tipo":"DISSERTATIVA","enunciado":"Qual é a função dos novos macrófagos formados por divisão local na pele e no subcutâneo?","alternativas":{},"resposta":"Atacar e destruir agentes infecciosos.","justificativa":"As células produzidas in situ exercem as funções protetoras usuais dos macrófagos.","dica":"Pense no alvo da resposta local."}]},{"numero":21,"id":"bloco-21","titulo":"Macrófagos nos linfonodos","sensivel":false,"busca_imagens":"linfonodo histologia seio subcapsular medular","busca_videos":"estrutura e função do linfonodo","texto":[{"t":"p","texto":"Macrófagos nos Linfonodos. Em essência, nenhuma partícula de substância que penetre nos tecidos, como as bactérias, pode ser absorvida diretamente através das membranas capilares para o sangue. Em vez disso, se essas partículas não são destruídas localmente nos tecidos, elas entram na linfa e drenam para os linfonodos situados de modo intermitente ao longo do curso do fluxo linfático. As partículas estranhas ficam aprisionadas nesses linfonodos na malha de seios revestidos por macrófagos teciduais."},{"t":"p","texto":"A Figura 33-3 ilustra a organização geral do linfonodo, mostrando a linfa entrando através da cápsula do linfonodo pelos vasos linfáticos aferentes, seguindo pelos seios medulares do linfonodo, e, por fim, saindo pelo hilo, pelos linfáticos eferentes que eventualmente se escoam para o sangue venoso."},{"t":"p","texto":"Grande número de macrófagos reveste os seios dos linfonodos, e se muitas partículas penetram nos seios pela linfa, os macrófagos fagocitam essas partículas e impedem sua disseminação geral por todo o corpo."}],"imagens":[{"id":"bloco-21-a","arquivo":"bloco-21-a.jpg","largura":768,"altura":1376,"alt":"Bloco 21, imagem 1 de 2: ARRANHÃO · LINFONODO · FILTRA A LINFA"},{"id":"bloco-21-b","arquivo":"bloco-21-b.jpg","largura":768,"altura":1376,"alt":"Bloco 21, imagem 2 de 2: ARRANHÃO · MACRÓFAGOS · RETÊM PARTÍCULAS"}],"questoes":[{"id":"Q21.01","tipo":"DIRETA","enunciado":"Para qual estrutura drenam partículas teciduais que não são destruídas localmente e entram na linfa?","alternativas":{},"resposta":"Linfonodos.","justificativa":"A linfa transporta essas partículas aos linfonodos ao longo do fluxo linfático.","dica":"São pontos de filtragem da linfa."},{"id":"Q21.02","tipo":"MULTIPLA","enunciado":"Qual sequência descreve o trajeto da linfa através do linfonodo?","alternativas":{"A":"Hilo → aferentes → cápsula → seios.","B":"Aferentes → seios → hilo → eferentes.","C":"Eferentes → seios → cápsula → hilo.","D":"Cápsula → eferentes → seios → sangue venoso."},"resposta":"B","justificativa":"A linfa entra por vasos aferentes na cápsula, atravessa seios medulares e sai pelo hilo por eferentes. A alternativa D inverte o papel dos eferentes e dos seios.","dica":"Aferente chega; eferente sai."},{"id":"Q21.03","tipo":"VF","enunciado":"Partículas bacterianas não destruídas no tecido podem alcançar os linfonodos pela linfa.","alternativas":{},"resposta":"Verdadeiro","justificativa":"Essa via substitui a absorção direta dessas partículas do tecido para o sangue capilar .","dica":"Siga a drenagem intersticial."},{"id":"Q21.04","tipo":"DISSERTATIVA","enunciado":"Que células revestem os seios dos linfonodos e retêm partículas estranhas?","alternativas":{},"resposta":"Macrófagos teciduais.","justificativa":"Os macrófagos dos seios fagocitam partículas trazidas pela linfa e limitam a disseminação.","dica":"Procure o fagócito da rede de seios."},{"id":"Q21.05","tipo":"DIRETA","enunciado":"Por onde a linfa sai do linfonodo antes de seguir nos vasos eferentes?","alternativas":{},"resposta":"Hilo.","justificativa":"Após percorrer os seios medulares, a linfa deixa o linfonodo pelo hilo.","dica":"É a região de saída do órgão."},{"id":"Q21.06","tipo":"VF","enunciado":"Os vasos linfáticos eferentes conduzem a linfa para dentro do linfonodo através da cápsula.","alternativas":{},"resposta":"Falso","justificativa":"A entrada pela cápsula ocorre nos vasos aferentes; os eferentes saem pelo hilo e acabam drenando para o sangue venoso.","dica":"O retorno fecha o circuito vascular."},{"id":"Q21.07","tipo":"DISSERTATIVA","enunciado":"Qual efeito da fagocitose nos seios linfonodais sobre a distribuição de partículas estranhas?","alternativas":{},"resposta":"Impede sua disseminação geral pelo corpo.","justificativa":"A retenção e ingestão das partículas nos seios limita sua passagem adiante.","dica":"Pense na função de filtro."}]},{"numero":22,"id":"bloco-22","titulo":"Macrófagos alveolares nos pulmões","sensivel":false,"busca_imagens":"macrófago alveolar histologia pulmão","busca_videos":"macrófagos alveolares silicose granuloma","texto":[{"t":"p","texto":"Macrófagos Alveolares nos Pulmões. Outra via pela qual microrganismos invasores frequentemente penetram no corpo é pelos pulmões. Grande número de macrófagos teciduais está presente como componentes integrais das paredes alveolares. Eles podem fagocitar partículas que ficam retidas nos alvéolos. Se as partículas são digeríveis, os macrófagos também podem digeri-las e liberar os produtos dessa digestão na linfa. Se a partícula não é digerível, os macrófagos, em geral, formam a cápsula de “célula gigante” ao redor da partícula até que em algum momento — se houver — ela possa ser dissolvida lentamente. Essas cápsulas são formadas, com fre-"},{"t":"leg","texto":"Figura 33-3 Diagrama funcional de linfonodo. (Redesenhado de Ham AW: Histology, 6th ed. Philadelphia: JB Lippincott, 1969.) (Modificada porGartner, HiattJL: ColorTextbookof Histology, 2nd ed. Philadelphia, WB Saunders, 2001.)"},{"t":"p","texto":"quência, em torno dos bacilos da tuberculose, partículas da poeira de sílica, e até mesmo partículas de carbono."},{"t":"p","texto":"N U"}],"imagens":[{"id":"bloco-22-a","arquivo":"bloco-22-a.jpg","largura":768,"altura":1376,"alt":"Bloco 22, imagem 1 de 2: POEIRA · MACRÓFAGO ALVEOLAR · REMOVE PARTÍCULAS"},{"id":"bloco-22-b","arquivo":"bloco-22-b.jpg","largura":768,"altura":1376,"alt":"Bloco 22, imagem 2 de 2: POEIRA · CÉLULA GIGANTE · ISOLA PARTÍCULA PERSISTENTE"}],"questoes":[{"id":"Q22.01","tipo":"DIRETA","enunciado":"Qual população fagocítica está integrada às paredes alveolares?","alternativas":{},"resposta":"Macrófagos alveolares.","justificativa":"Essas células teciduais estão presentes nas paredes dos alvéolos pulmonares.","dica":"O nome inclui a localização."},{"id":"Q22.02","tipo":"MULTIPLA","enunciado":"Qual é o destino de partículas alveolares digeríveis após fagocitose?","alternativas":{"A":"Produtos seguem para a linfa.","B":"Partículas seguem para a bile.","C":"Produtos seguem para a urina.","D":"Partículas seguem ao baço."},"resposta":"A","justificativa":"Os macrófagos digerem essas partículas e liberam os produtos na linfa. A bile não é indicada como destino dos produtos alveolares.","dica":"Procure a via de drenagem tecidual."},{"id":"Q22.03","tipo":"VF","enunciado":"Macrófagos alveolares podem fagocitar partículas retidas nos alvéolos.","alternativas":{},"resposta":"Verdadeiro","justificativa":"Essa é a função protetora local atribuída às células das paredes alveolares.","dica":"Pense na remoção local de partículas inaladas."},{"id":"Q22.04","tipo":"DISSERTATIVA","enunciado":"Como os macrófagos alveolares geralmente isolam uma partícula não digerível?","alternativas":{},"resposta":"Formam uma cápsula de célula gigante ao redor dela.","justificativa":"A cápsula mantém a partícula envolvida até eventual dissolução lenta.","dica":"Quando não há digestão, ocorre isolamento."},{"id":"Q22.05","tipo":"MULTIPLA","enunciado":"Assinale a exceção entre os materiais que formam cápsulas de célula gigante no pulmão.","alternativas":{"A":"Bacilos tuberculosos.","B":"Poeira de sílica.","C":"Partículas de carbono.","D":"Produtos da digestão."},"resposta":"D","justificativa":"Produtos da digestão de partículas digeríveis são liberados na linfa, enquanto partículas não digeríveis podem ser encapsuladas. O carbono é um exemplo de partícula que pode ser encapsulada.","dica":"Três exemplos se relacionam ao ar inalado ou à infecção pulmonar."},{"id":"Q22.06","tipo":"VF","enunciado":"Uma partícula não digerível envolvida por macrófagos alveolares pode permanecer até eventual dissolução lenta.","alternativas":{},"resposta":"Verdadeiro","justificativa":"A dissolução lenta pode até não ocorrer.","dica":"O isolamento pode ser prolongado."},{"id":"Q22.07","tipo":"DISSERTATIVA","enunciado":"Cite os três exemplos de material ao redor do qual podem se formar cápsulas de célula gigante.","alternativas":{},"resposta":"Bacilos da tuberculose, poeira de sílica e partículas de carbono.","justificativa":"Esses são os exemplos enumerados de partículas persistentes nos alvéolos.","dica":"Um microrganismo e dois particulados."}]},{"numero":23,"id":"bloco-23","titulo":"Células de Kupffer nos sinusoides hepáticos","sensivel":false,"busca_imagens":"células de Kupffer sinusoide hepático","busca_videos":"células de Kupffer função fígado","texto":[{"t":"p","texto":"Macrófagos (Células de Kupffer) nos Sinusoides Hepáticos. Outra via favorita para a invasão bacteriana do corpo é pelo trato gastrointestinal. Grande número de bactérias oriundas dos alimentos ingeridos passa constantemente através da mucosa gastrointestinal para o sangue porta. Antes que esse sangue entre na circulação geral, ele passa pelos sinusoides do fígado que são revestidos por macrófagos teciduais chamados de células de Kupffer, mostradas na Figura 33-4. Essas células formam sistema de filtragem de partículas tão eficaz que quase nenhuma bactéria do trato gastrointestinal passa do sangue porta para a circulação sistêmica. Registros em vídeo da fagocitose pelas células de Kupffer demonstraram a fagocitose de bactéria em menos de 1/100 de segundo."}],"imagens":[{"id":"bloco-23-a","arquivo":"bloco-23-a.jpg","largura":768,"altura":1376,"alt":"Bloco 23, imagem 1 de 1: ALIMENTO · CÉLULA DE KUPFFER · FILTRA SANGUE PORTA"}],"questoes":[{"id":"Q23.01","tipo":"DIRETA","enunciado":"Como se chamam os macrófagos que revestem os sinusoides hepáticos?","alternativas":{},"resposta":"Células de Kupffer.","justificativa":"Esse é o nome dado aos macrófagos teciduais dos sinusoides do fígado.","dica":"Trata-se de um epônimo hepático."},{"id":"Q23.02","tipo":"MULTIPLA","enunciado":"Por qual via sanguínea chegam ao fígado bactérias que atravessaram a mucosa gastrointestinal?","alternativas":{"A":"Veia cava.","B":"Veia pulmonar.","C":"Sangue porta.","D":"Artéria renal."},"resposta":"C","justificativa":"Bactérias oriundas do trato gastrointestinal passam para o sangue porta, filtrado no fígado. A veia pulmonar não conduz o sangue intestinal ao fígado.","dica":"Pense no fluxo vindo do intestino."},{"id":"Q23.03","tipo":"VF","enunciado":"Os sinusoides hepáticos são atravessados pelo sangue porta antes de ele alcançar a circulação geral.","alternativas":{},"resposta":"Verdadeiro","justificativa":"Essa disposição permite a filtragem das partículas pelas células de Kupffer.","dica":"O fígado fica antes do circuito sistêmico."},{"id":"Q23.04","tipo":"DISSERTATIVA","enunciado":"Que efeito têm as células de Kupffer sobre as bactérias provenientes do trato gastrointestinal?","alternativas":{},"resposta":"Filtram e fagocitam quase todas antes da circulação sistêmica.","justificativa":"O sistema de filtração é tão eficaz que quase nenhuma bactéria passa adiante.","dica":"Considere uma barreira entre intestino e circulação geral."},{"id":"Q23.05","tipo":"DIRETA","enunciado":"Em menos de que intervalo a fagocitose bacteriana por células de Kupffer foi observada em vídeo?","alternativas":{},"resposta":"1/100 de segundo.","justificativa":"A fagocitose de uma bactéria pode ocorrer em menos de um centésimo de segundo.","dica":"É uma fração muito breve de segundo."},{"id":"Q23.06","tipo":"VF","enunciado":"Bactérias oriundas dos alimentos alcançam a circulação sistêmica antes de passar pelos sinusoides hepáticos.","alternativas":{},"resposta":"Falso","justificativa":"Elas chegam ao sangue porta e passam pelos sinusoides hepáticos antes da circulação geral.","dica":"Relacione alimento, intestino e sistema porta."}]},{"numero":24,"id":"bloco-24","titulo":"Macrófagos do baço e da medula óssea","sensivel":false,"busca_imagens":"baço polpa vermelha seios venosos histologia","busca_videos":"baço polpa vermelha e branca função","texto":[{"t":"p","subtitulo":"Macrófagos do Baço e da Medula Óssea. Se o","texto":"organismo invasor consegue penetrar na circulação geral, existem outras linhas de defesa do sistema de macrófagos teciduais, especialmente por meio dos macrófagos do baço e da medula óssea. Nesses dois tecidos, os macrófagos ficam retidos pela malha reticular desses órgãos, e quando as partículas estranhas entram em contato com esses macrófagos, são fagocitadas."},{"t":"p","texto":"O baço é similar aos linfonodos, exceto pelo fato de que sangue, em vez de linfa, flui pelos espaços teciduais do órgão. A Figura 33-5 mostra pequeno segmento periférico do tecido esplênico. Observe que pequena artéria entra através da cápsula esplênica na polpa esplênica, terminando como pequenos capilares. Os capilares são extremamente porosos, permitindo que todo o sangue passe dos capilares para os cordões da polpa vermelha."},{"t":"leg","texto":"Figura 33-4 Células de Kupffer revestindo os sinusoides hepáticos, demonstrando a fagocitose de partículas de nanquim no citoplasma das células de Kupffer. (Redesenhado de Copenhaver WM, et al: Bailey's Textbook of Histology, 10th ed. Baltimore: Williams & Wilkins, 1971.)"},{"t":"leg","texto":"Figura 33-5 Estruturas funcionais do baço. (Modificado de Bloom W, Fawcett DW: A Textbook of Histology, 10th ed. Philadelphia: WB Saunders, 1975.)"},{"t":"p","texto":"A seguir, o sangue gradativamente se espreme pela rede trabecular desses cordões, para após certo tempo retornar à circulação através das paredes endoteliais dos seios venosos. As trabéculas da polpa vermelha são revestidas por grande número de macrófagos, como também o são os seios venosos. Essa passagem peculiar do sangue pelos cordões da polpa vermelha representa meio excepcional de fagocitose de detritos indesejáveis encontrados no sangue, incluindo especialmente hemácias senis e anormais."}],"imagens":[{"id":"bloco-24-a","arquivo":"bloco-24-a.jpg","largura":768,"altura":1376,"alt":"Bloco 24, imagem 1 de 3: SANGUE · BAÇO · FILTRA O SANGUE"},{"id":"bloco-24-b","arquivo":"bloco-24-b.jpg","largura":768,"altura":1376,"alt":"Bloco 24, imagem 2 de 3: SANGUE · MACRÓFAGOS ESPLÊNICOS · FAGOCITAM PARTÍCULAS"},{"id":"bloco-24-c","arquivo":"bloco-24-c.jpg","largura":768,"altura":1376,"alt":"Bloco 24, imagem 3 de 3: HEMÁCIA VELHA · MACRÓFAGOS DO BAÇO · REMOVEM HEMÁCIAS VELHAS"}],"questoes":[{"id":"Q24.01","tipo":"DIRETA","enunciado":"Além do baço, qual tecido possui macrófagos destacados como defesa após a entrada do invasor na circulação geral?","alternativas":{},"resposta":"Medula óssea.","justificativa":"Macrófagos do baço e da medula óssea constituem linhas adicionais de defesa.","dica":"É também um sítio hematopoético."},{"id":"Q24.02","tipo":"MULTIPLA","enunciado":"O baço é comparado ao linfonodo porque ambos filtram partículas; qual fluido atravessa os espaços teciduais esplênicos?","alternativas":{"A":"Linfa dos linfonodos.","B":"Sangue circulante.","C":"Bile hepática.","D":"Líquido pleural."},"resposta":"B","justificativa":"O baço filtra sangue, ao passo que o linfonodo recebe linfa. A alternativa A confunde a função do baço com a do linfonodo.","dica":"Pense no fluido que carrega hemácias senis."},{"id":"Q24.03","tipo":"VF","enunciado":"Macrófagos do baço e da medula óssea ficam retidos pela malha reticular desses órgãos.","alternativas":{},"resposta":"Verdadeiro","justificativa":"Sua retenção os posiciona para fagocitar partículas que entram em contato com a malha.","dica":"Visualize uma rede de filtragem."},{"id":"Q24.04","tipo":"DISSERTATIVA","enunciado":"Qual o trajeto inicial do sangue ao entrar no baço pela cápsula até alcançar os cordões da polpa vermelha?","alternativas":{},"resposta":"Pequena artéria, polpa esplênica e capilares porosos, que liberam sangue nos cordões.","justificativa":"A porosidade capilar permite a passagem do sangue para os cordões da polpa vermelha.","dica":"Siga artéria, capilar e cordão."},{"id":"Q24.05","tipo":"MULTIPLA","enunciado":"Por qual estrutura o sangue retorna à circulação após atravessar os cordões da polpa vermelha?","alternativas":{"A":"Parede dos seios venosos.","B":"Cápsula dos linfonodos.","C":"Membrana alveolar basal.","D":"Ductos biliares hepáticos."},"resposta":"A","justificativa":"O sangue atravessa as paredes endoteliais dos seios venosos para retornar à circulação. A cápsula linfonodal pertence a outro órgão filtrador.","dica":"O retorno ocorre por canais venosos."},{"id":"Q24.06","tipo":"VF","enunciado":"Trabéculas da polpa vermelha e seios venosos são revestidos por grande número de macrófagos.","alternativas":{},"resposta":"Verdadeiro","justificativa":"Esses macrófagos contribuem para a remoção de detritos durante a passagem do sangue.","dica":"Pense nas superfícies do trajeto sanguíneo."},{"id":"Q24.07","tipo":"DISSERTATIVA","enunciado":"Que componentes sanguíneos são especialmente removidos pela fagocitose esplênica?","alternativas":{},"resposta":"Hemácias senis e anormais.","justificativa":"A passagem peculiar pela polpa vermelha facilita a fagocitose desses detritos sanguíneos.","dica":"Pense em células vermelhas envelhecidas."}]},{"numero":25,"id":"bloco-25","titulo":"Inflamação: definição","sensivel":false,"busca_imagens":"sinais cardinais da inflamação","busca_videos":"inflamação aguda visão geral","texto":[{"t":"h","texto":"Inflamação: O Papel dos Neutrófilos e Macrófagos"},{"t":"h","texto":"Inflamação"},{"t":"p","texto":"Quando ocorre lesão tecidual, seja ela causada por bactérias, trauma, agentes químicos, calor ou qualquer outro fenômeno, diversas substâncias são liberadas pelos tecidos danificados, causando dramáticas alterações secundárias nos tecidos não lesionados ao redor. Todo esse complexo de alterações teciduais é chamado de inflamação."}],"imagens":[{"id":"bloco-25-a","arquivo":"bloco-25-a.jpg","largura":768,"altura":1376,"alt":"Bloco 25, imagem 1 de 1: CALOR · INFLAMAÇÃO · RESPONDE À LESÃO"}],"questoes":[{"id":"Q25.01","tipo":"DIRETA","enunciado":"Como se chama o complexo de alterações em tecidos vizinhos após uma lesão tecidual?","alternativas":{},"resposta":"Inflamação.","justificativa":"Substâncias liberadas pelo tecido danificado desencadeiam alterações secundárias que, em conjunto, constituem a inflamação.","dica":"É a resposta local à lesão."},{"id":"Q25.02","tipo":"MULTIPLA","enunciado":"Qual sequência causal caracteriza a resposta inflamatória à lesão tecidual?","alternativas":{"A":"Mediadores → lesão → reparação local.","B":"Lesão → mediadores → alterações vizinhas.","C":"Alterações vizinhas → lesão → mediadores locais.","D":"Reparação → mediadores → lesão tecidual."},"resposta":"B","justificativa":"A lesão leva à liberação de substâncias que alteram os tecidos ao redor. A alternativa A inverte a ordem inicial, colocando os mediadores antes da lesão.","dica":"Comece pelo evento que danifica o tecido."},{"id":"Q25.03","tipo":"VF","enunciado":"Substâncias liberadas por tecidos danificados podem alterar tecidos próximos que não foram inicialmente lesionados.","alternativas":{},"resposta":"Verdadeiro","justificativa":"Essas alterações secundárias nos tecidos vizinhos integram o processo inflamatório.","dica":"A resposta ultrapassa o ponto inicial da lesão."},{"id":"Q25.04","tipo":"DISSERTATIVA","enunciado":"Qual evento conecta a lesão inicial às alterações inflamatórias nos tecidos ao redor?","alternativas":{},"resposta":"Liberação de substâncias pelos tecidos danificados.","justificativa":"Os mediadores liberados após a lesão causam as alterações secundárias dos tecidos vizinhos.","dica":"Procure o sinal que sai do tecido lesado."},{"id":"Q25.05","tipo":"DISSERTATIVA","enunciado":"Cite quatro tipos de agressão capazes de iniciar lesão tecidual inflamatória.","alternativas":{},"resposta":"Bactérias, trauma, agentes químicos e calor.","justificativa":"Esses fatores podem lesar tecidos e iniciar a liberação de substâncias que afetam áreas vizinhas.","dica":"Inclua agente infeccioso, dano mecânico, químico e térmico."}]},{"numero":26,"id":"bloco-26","titulo":"Características da inflamação e mediadores","sensivel":false,"busca_imagens":"inflamação aguda vasodilatação permeabilidade vascular exsudato","busca_videos":"mediadores químicos da inflamação histamina bradicinina","texto":[{"t":"p","texto":"A inflamação se caracteriza por (1) vasodilatação dos vasos sanguíneos locais, com o consequente aumento do fluxo sanguíneo local; (2) aumento da permeabilidade dos capilares, permitindo a saída de grande quantidade de líquido para os espaços intersticiais; (3) coagulação do líquido nos espaços intersticiais, devido à quantidade aumentada de fibrinogênio e outras proteínas que saíram dos capilares; (4) migração de grande quantidade de granulócitos e monócitos para os tecidos e (5) dilatação das células teciduais. Alguns dos muitos produtos teciduais causadores dessas reações incluem a histamina, a bradicinina, a serotonina, as prostaglandinas, diversos produtos da reação do sistema de complemento (descrito no Cap. 34), produtos da reação do sistema da coagulação sanguínea e várias substâncias designadas como linfocinas, liberadas pelas células T sensibilizadas (parte do sistema imune; também discutidas no Cap. 34). Várias dessas substâncias ativam com grande intensidade o sistema macrofágico, e, dentro de algumas horas, os macrófagos começam a devorar os tecidos destruídos. Mas, por vezes, os macrófagos também lesionam as células teciduais ainda vivas."}],"imagens":[{"id":"bloco-26-a","arquivo":"bloco-26-a.jpg","largura":768,"altura":1376,"alt":"Bloco 26, imagem 1 de 3: LESÃO · INFLAMAÇÃO · ALTERA VASOS E TECIDOS"},{"id":"bloco-26-b","arquivo":"bloco-26-b.jpg","largura":768,"altura":1376,"alt":"Bloco 26, imagem 2 de 3: LESÃO · MEDIADORES · ATIVAM A RESPOSTA"},{"id":"bloco-26-c","arquivo":"bloco-26-c.jpg","largura":768,"altura":1376,"alt":"Bloco 26, imagem 3 de 3: LESÃO · MACRÓFAGOS · REMOVEM DETRITOS"}],"questoes":[{"id":"Q26.01","tipo":"DIRETA","enunciado":"Qual alteração vascular local eleva o fluxo sanguíneo durante a inflamação?","alternativas":{},"resposta":"Vasodilatação.","justificativa":"A dilatação dos vasos locais aumenta o fluxo sanguíneo na área inflamada.","dica":"O vaso fica mais amplo."},{"id":"Q26.02","tipo":"MULTIPLA","enunciado":"Qual alteração capilar permite a saída de grande quantidade de líquido para o interstício inflamado?","alternativas":{"A":"Aumento da permeabilidade.","B":"Diminuição da pressão local.","C":"Redução da luz vascular.","D":"Aumento da viscosidade."},"resposta":"A","justificativa":"O aumento da permeabilidade capilar facilita a saída de líquido. A redução da luz vascular contraria a vasodilatação local.","dica":"Pense em paredes vasculares mais permeáveis."},{"id":"Q26.03","tipo":"VF","enunciado":"A coagulação do líquido intersticial inflamado é associada à saída de fibrinogênio e outras proteínas dos capilares.","alternativas":{},"resposta":"Verdadeiro","justificativa":"A presença aumentada dessas proteínas no interstício favorece a coagulação local.","dica":"Relacione extravasamento de proteína e coágulo."},{"id":"Q26.04","tipo":"DISSERTATIVA","enunciado":"Quais leucócitos migram em grande quantidade para os tecidos durante a inflamação?","alternativas":{},"resposta":"Granulócitos e monócitos.","justificativa":"A migração abundante dessas células é uma das características enumeradas da inflamação.","dica":"Pense em células fagocíticas recrutadas."},{"id":"Q26.05","tipo":"DIRETA","enunciado":"Que células liberam linfocinas durante a inflamação?","alternativas":{},"resposta":"Células T sensibilizadas.","justificativa":"As linfocinas são atribuídas às células T sensibilizadas.","dica":"O nome do mediador sugere a linhagem."},{"id":"Q26.06","tipo":"MULTIPLA","enunciado":"Assinale a exceção entre os mediadores inflamatórios nomeados.","alternativas":{"A":"Histamina.","B":"Bradicinina tecidual.","C":"Serotonina.","D":"Hemoglobina."},"resposta":"D","justificativa":"Histamina, bradicinina e serotonina são mediadores enumerados, assim como prostaglandinas e produtos de cascatas. Hemoglobina não aparece como mediador dessa resposta.","dica":"Três alternativas são aminas ou peptídeo sinalizador."},{"id":"Q26.07","tipo":"VF","enunciado":"As linfocinas envolvidas na inflamação são liberadas por granulócitos recém-chegados ao tecido.","alternativas":{},"resposta":"Falso","justificativa":"As linfocinas são liberadas por células T sensibilizadas.","dica":"Inclua lipídios e produtos de cascatas."},{"id":"Q26.08","tipo":"DISSERTATIVA","enunciado":"Além das alterações vasculares e da migração leucocitária, que mudança ocorre nas células do tecido inflamado?","alternativas":{},"resposta":"Dilatação das células teciduais.","justificativa":"A dilatação das células teciduais integra as características da inflamação.","dica":"Considere o tamanho das células locais."},{"id":"Q26.09","tipo":"VF","enunciado":"Macrófagos ativados podem começar a devorar tecidos destruídos em algumas horas e, às vezes, lesionar células ainda vivas.","alternativas":{},"resposta":"Verdadeiro","justificativa":"A ativação intensa permite remover tecido destruído, mas também pode lesionar células vivas.","dica":"A resposta pode atingir tecido preservado."},{"id":"Q26.10","tipo":"DISSERTATIVA","enunciado":"Qual é o efeito inicial das substâncias inflamatórias sobre o sistema macrofágico?","alternativas":{},"resposta":"Ativação intensa dos macrófagos.","justificativa":"Essa ativação precede a remoção de tecidos destruídos, que se inicia em poucas horas.","dica":"Pense na preparação do fagócito."},{"id":"Q26.11","tipo":"MULTIPLA","enunciado":"Assinale as duas afirmações corretas. I. A vasodilatação local aumenta o fluxo sanguíneo. II. A permeabilidade aumentada impede a saída de líquido. III. Células T sensibilizadas liberam linfocinas. IV. Macrófagos ativados poupam todas as células vivas.","alternativas":{"A":"I e III.","B":"I e II.","C":"II e IV.","D":"III e IV."},"resposta":"A","justificativa":"I e III estão corretas: a vasodilatação eleva o fluxo e células T sensibilizadas liberam linfocinas. II inverte o efeito da permeabilidade; IV contradiz a possibilidade de lesão de células vivas.","dica":"Pense no fluxo vascular e na origem das linfocinas."},{"id":"Q26.12","tipo":"DIRETA","enunciado":"Além de histamina, bradicinina e serotonina, qual mediador nominal participa das reações inflamatórias?","alternativas":{},"resposta":"Prostaglandinas.","justificativa":"Prostaglandinas integram a relação de substâncias que causam reações inflamatórias.","dica":"É o quarto nome da sequência de mediadores."},{"id":"Q26.13","tipo":"DISSERTATIVA","enunciado":"Quais grupos de produtos de cascatas e de células T sensibilizadas participam da inflamação?","alternativas":{},"resposta":"Produtos do complemento, produtos da coagulação e linfocinas.","justificativa":"Essas três classes somam-se a histamina, bradicinina, serotonina e prostaglandinas na resposta inflamatória.","dica":"Pense em duas cascatas e uma secreção linfocitária."}]},{"numero":27,"id":"bloco-27","titulo":"Efeito de emparedamento da inflamação","sensivel":true,"busca_imagens":"abscesso cutâneo formação cápsula fibrina","busca_videos":"inflamação aguda abscesso formação","texto":[{"t":"p","texto":"Efeito de \"Emparedamento\" da Inflamação. Um dos primeiros resultados da inflamação é o “emparedamento” da área lesada, isolando-a dos tecidos a seu redor. Os espaços teciduais e os vasos linfáticos, na área inflamada, são bloqueados por coágulos de fibrinogênio de modo que, após algum tempo, líquido quase não consegue fluir por esses espaços. Esse processo de isolamento retarda a disseminação de bactérias ou de produtos tóxicos."}],"imagens":[{"id":"bloco-27-a","arquivo":"bloco-27-a.jpg","largura":768,"altura":1376,"alt":"Bloco 27, imagem 1 de 1: INFECÇÃO · FIBRINA · ISOLA O FOCO"}],"questoes":[{"id":"Q27.01","tipo":"DIRETA","enunciado":"Como é denominado o isolamento precoce da área lesada durante a inflamação?","alternativas":{},"resposta":"Emparedamento.","justificativa":"O termo designa o isolamento da área inflamada em relação aos tecidos ao redor.","dica":"O nome sugere criar uma barreira."},{"id":"Q27.02","tipo":"MULTIPLA","enunciado":"Qual mecanismo bloqueia espaços teciduais e vasos linfáticos na área inflamada?","alternativas":{"A":"Contração de hemácias locais.","B":"Coágulos derivados do fibrinogênio.","C":"Acúmulo de anticorpos capilares.","D":"Dilatação dos vasos linfáticos locais."},"resposta":"B","justificativa":"Coágulos derivados do fibrinogênio bloqueiam essas vias e reduzem o fluxo de líquido. A dilatação dos vasos linfáticos não produz o bloqueio responsável pelo emparedamento.","dica":"Pense no material da coagulação."},{"id":"Q27.03","tipo":"VF","enunciado":"O emparedamento inflamatório aumenta o fluxo de líquido pelos espaços teciduais e vasos linfáticos locais.","alternativas":{},"resposta":"Falso","justificativa":"Os coágulos bloqueiam essas vias, de modo que o líquido quase deixa de fluir.","dica":"O isolamento depende de reduzir a circulação local."},{"id":"Q27.04","tipo":"DISSERTATIVA","enunciado":"Qual consequência protetora resulta do emparedamento inflamatório?","alternativas":{},"resposta":"Retardo da disseminação de bactérias e produtos tóxicos.","justificativa":"O isolamento da área lesada dificulta o espalhamento desses agentes.","dica":"Pense na contenção do foco."},{"id":"Q27.05","tipo":"VF","enunciado":"O emparedamento é um dos primeiros resultados da inflamação.","alternativas":{},"resposta":"Verdadeiro","justificativa":"A formação precoce da barreira é destacada no início do processo inflamatório.","dica":"Considere a ordem temporal."}]},{"numero":28,"id":"bloco-28","titulo":"Intensidade da inflamação: estafilococos versus estreptococos","sensivel":true,"busca_imagens":"Staphylococcus aureus abscesso Streptococcus celulite","busca_videos":"estafilococo e estreptococo diferenças patogênese","texto":[{"t":"p","texto":"A intensidade do processo inflamatório é, em geral, proporcional ao grau da lesão tecidual. Por exemplo, quando estafüococos invadem os tecidos, eles liberam toxinas celulares extremamente letais. Como resultado, a inflamação se desenvolve com muita rapidez — na verdade, com velocidade muito maior que a capacidade de os estafilococos se multiplicarem e disseminarem-se. Assim, a infecção estafilocócica local, em pouco tempo e de forma característica, é emparedada, impedindo sua disseminação por todo o corpo. Os estreptococos, em contraste, não causam destruição tão intensa dos tecidos locais. Por isso, o processo de emparedamento se desenvolve mais lentamente, dentro de período de muitas horas, enquanto muitos estreptococos se reproduzem e migram. Consequentemente, os estreptococos têm tendência muito maior de se disseminar pelo corpo e de causar morte do que os estafilococos, mesmo que os estafilococos sejam muito mais destrutivos para os tecidos."}],"imagens":[{"id":"bloco-28-a","arquivo":"bloco-28-a.jpg","largura":768,"altura":1376,"alt":"Bloco 28, imagem 1 de 2: BACTÉRIAS · ESTAFILOCOCO · CAUSA DANO LOCAL INTENSO"},{"id":"bloco-28-b","arquivo":"bloco-28-b.jpg","largura":768,"altura":1376,"alt":"Bloco 28, imagem 2 de 2: BACTÉRIAS · ESTREPTOCOCO · PODE SE DISSEMINAR"}],"questoes":[{"id":"Q28.01","tipo":"DIRETA","enunciado":"Em geral, a intensidade da inflamação é proporcional a qual parâmetro?","alternativas":{},"resposta":"Grau da lesão tecidual.","justificativa":"A intensidade inflamatória geralmente acompanha a magnitude da lesão tecidual.","dica":"Mais dano gera resposta maior."},{"id":"Q28.02","tipo":"MULTIPLA","enunciado":"Qual associação descreve a infecção estafilocócica local?","alternativas":{"A":"Lesão discreta e disseminação rápida.","B":"Lesão discreta e isolamento tardio.","C":"Toxinas letais e emparedamento rápido.","D":"Toxinas fracas e migração bacteriana prolongada."},"resposta":"C","justificativa":"Estafilococos liberam toxinas muito letais, gerando inflamação e emparedamento rápidos. A alternativa A se aproxima do padrão atribuído aos estreptococos.","dica":"A lesão intensa precipita a barreira."},{"id":"Q28.03","tipo":"VF","enunciado":"Na infecção estafilocócica, a inflamação estafilocócica pode progredir mais rapidamente que a multiplicação e a disseminação das bactérias.","alternativas":{},"resposta":"Verdadeiro","justificativa":"Essa rapidez permite o isolamento precoce do foco local.","dica":"Compare velocidade da resposta com a do agente."},{"id":"Q28.04","tipo":"DISSERTATIVA","enunciado":"Por que os estreptococos têm maior tendência à disseminação sistêmica nessa comparação?","alternativas":{},"resposta":"Causam menor destruição local, com emparedamento mais lento enquanto se reproduzem e migram.","justificativa":"A formação tardia da barreira dá tempo para a multiplicação e a migração estreptocócicas.","dica":"O ponto decisivo é a demora do isolamento."},{"id":"Q28.05","tipo":"MULTIPLA","enunciado":"Qual infecção tende a maior disseminação corporal e risco de morte em comparação com a infecção estafilocócica?","alternativas":{"A":"Infecção estreptocócica.","B":"Estafilococos.","C":"Ambas com igual tendência.","D":"Infecção por ambos os gêneros."},"resposta":"A","justificativa":"Estreptococos tendem mais à disseminação e à morte, apesar de causarem menos destruição tecidual local. Estafilococos são mais destrutivos localmente, mas costumam ser emparedados rapidamente.","dica":"Diferencie dano local de disseminação."},{"id":"Q28.06","tipo":"VF","enunciado":"Os estafilococos são mais destrutivos para os tecidos locais que os estreptococos, apesar da menor tendência à disseminação corporal.","alternativas":{},"resposta":"Verdadeiro","justificativa":"A lesão intensa acelera a inflamação e o emparedamento, restringindo sua propagação.","dica":"Relacione agressividade local e contenção."},{"id":"Q28.07","tipo":"DISSERTATIVA","enunciado":"Em que escala temporal o emparedamento da infecção estreptocócica se desenvolve ?","alternativas":{},"resposta":"Ao longo de muitas horas.","justificativa":"A barreira se forma mais lentamente, permitindo reprodução e migração bacterianas nesse intervalo.","dica":"Compare com o isolamento rápido do estafilococo."}]},{"numero":29,"id":"bloco-29","titulo":"Macrófago tecidual: primeira linha de defesa","sensivel":false,"busca_imagens":"macrófagos residentes micróglia histiócito alveolar","busca_videos":"resposta inflamatória macrófagos primeira linha de defesa","texto":[{"t":"h","texto":"Respostas dos Macrófagos e Neutrófilos durante a Inflamação"},{"t":"p","texto":"O Macrófago Tecidual É a Primeira Linha de Defesa Contra a Infecção. Alguns minutos após o início da inflamação, os macrófagos já estão presentes nos tecidos, sejam eles histiócitos nos tecidos subcutâneos, macrófagos alveolares nos pulmões, micróglia no cérebro, ou outros, iniciando imediatamente suas ações fagocíticas. Quando ativados pelos produtos da infecção e da inflamação, o primeiro efeito é o rápido aumento do tamanho de cada uma dessas células. A seguir, muitos dos macrófagos previamente sésseis se soltam de suas ligações e passam a ser móveis, formando a primeira linha de defesa contra as infecções durante a primeira hora. O número desses macrófagos mobilizados inicialmente não é grande, mas são todos salvadores da vida."}],"imagens":[{"id":"bloco-29-a","arquivo":"bloco-29-a.jpg","largura":768,"altura":1376,"alt":"Bloco 29, imagem 1 de 1: MICRÓBIO · MACRÓFAGO RESIDENTE · PRIMEIRA DEFESA"}],"questoes":[{"id":"Q29.01","tipo":"DIRETA","enunciado":"Qual célula constitui a primeira linha de defesa após o início da inflamação?","alternativas":{},"resposta":"Macrófago tecidual.","justificativa":"Macrófagos residentes já estão nos tecidos e iniciam prontamente a fagocitose.","dica":"O primeiro defensor já está no local."},{"id":"Q29.02","tipo":"MULTIPLA","enunciado":"Qual associação entre macrófago residente e tecido está correta?","alternativas":{"A":"Histiócito — cérebro.","B":"Micróglia — pulmão.","C":"Alveolar — subcutâneo.","D":"Micróglia — cérebro."},"resposta":"D","justificativa":"A micróglia é o exemplo de macrófago residente cerebral. Histiócitos são associados ao tecido subcutâneo, não ao cérebro.","dica":"Lembre o nome próprio do fagócito cerebral."},{"id":"Q29.03","tipo":"VF","enunciado":"Macrófagos residentes podem iniciar a fagocitose poucos minutos após o início da inflamação.","alternativas":{},"resposta":"Verdadeiro","justificativa":"Sua presença prévia nos tecidos permite resposta imediata.","dica":"Eles não precisam chegar pelo sangue."},{"id":"Q29.04","tipo":"DISSERTATIVA","enunciado":"Qual é a primeira mudança nos macrófagos ativados por produtos da infecção e da inflamação?","alternativas":{},"resposta":"Aumento rápido de tamanho.","justificativa":"O aumento celular precede o desprendimento e a mobilização de muitos macrófagos fixos.","dica":"Antes de migrar, a célula cresce."},{"id":"Q29.05","tipo":"VF","enunciado":"Macrófagos previamente fixos permanecem presos aos tecidos durante toda a primeira hora da inflamação.","alternativas":{},"resposta":"Falso","justificativa":"Muitos se soltam de suas ligações e tornam-se móveis nesse intervalo.","dica":"O residente passa a patrulhar."},{"id":"Q29.06","tipo":"DISSERTATIVA","enunciado":"Cite os três exemplos de macrófagos residentes com suas localizações na primeira linha de defesa.","alternativas":{},"resposta":"Histiócitos no subcutâneo, macrófagos alveolares no pulmão e micróglia no cérebro.","justificativa":"Esses exemplos mostram a presença de fagócitos residentes em diferentes tecidos.","dica":"Pense em pele, pulmão e sistema nervoso."},{"id":"Q29.07","tipo":"VF","enunciado":"O contingente inicial de macrófagos mobilizados não é grande, embora tenha papel vital na defesa.","alternativas":{},"resposta":"Verdadeiro","justificativa":"Mesmo em pequeno número, os macrófagos mobilizados inicialmente têm papel vital.","dica":"Quantidade pequena não implica efeito pequeno."}]},{"numero":30,"id":"bloco-30","titulo":"Neutrófilos: segunda linha de defesa (~1 hora)","sensivel":false,"busca_imagens":"migração de neutrófilos inflamação aguda","busca_videos":"recrutamento de neutrófilos TNF IL-1","texto":[{"t":"p","texto":"A Invasão por Neutrófilos das Áreas Inflamadas É a Segunda Linha de Defesa. Aproximadamente 1 hora após o início da inflamação, grande número de neutrófilos invade a área inflamada a partir do sangue. Isso é causado por citocinas inflamatórias (p. ex., TNF, IL-1) e outros produtos bioquímicos produzidos pelos tecidos inflamados que iniciam as reações a seguir:"}],"imagens":[{"id":"bloco-30-a","arquivo":"bloco-30-a.jpg","largura":768,"altura":1376,"alt":"Bloco 30, imagem 1 de 1: CITOCINAS · NEUTRÓFILO · SEGUNDA DEFESA"}],"questoes":[{"id":"Q30.01","tipo":"DIRETA","enunciado":"Qual leucócito constitui a segunda linha de defesa nas áreas inflamadas?","alternativas":{},"resposta":"Neutrófilo.","justificativa":"Muitos neutrófilos invadem o foco a partir do sangue após a resposta inicial dos macrófagos.","dica":"É o granulócito predominante."},{"id":"Q30.02","tipo":"MULTIPLA","enunciado":"Aproximadamente quando muitos neutrófilos invadem a área inflamada a partir do sangue?","alternativas":{"A":"Em poucos segundos.","B":"Após vários dias.","C":"Cerca de uma hora.","D":"Após muitos meses."},"resposta":"C","justificativa":"A invasão neutrofílica ocorre por volta de uma hora após o início da inflamação. O intervalo de vários dias não corresponde à resposta inicial.","dica":"O intervalo é medido em horas."},{"id":"Q30.03","tipo":"VF","enunciado":"TNF e IL-1 são citocinas que impedem a invasão neutrofílica do tecido inflamado.","alternativas":{},"resposta":"Falso","justificativa":"Elas integram os produtos inflamatórios que iniciam as reações associadas à invasão de neutrófilos.","dica":"São duas citocinas nomeadas no trecho."},{"id":"Q30.04","tipo":"DISSERTATIVA","enunciado":"De onde provém o grande contingente de neutrófilos que invade a área inflamada?","alternativas":{},"resposta":"Do sangue.","justificativa":"Os neutrófilos recrutados deixam o sangue e entram na área inflamada.","dica":"Diferencie residente tecidual de recrutado circulante."},{"id":"Q30.05","tipo":"VF","enunciado":"A invasão neutrofílica constitui a segunda linha de defesa após a atuação inicial dos macrófagos teciduais.","alternativas":{},"resposta":"Verdadeiro","justificativa":"A sequência temporal coloca macrófagos residentes primeiro e neutrófilos sanguíneos depois.","dica":"Lembre a ordem das duas linhas."}]}]};
